// Reference (справочник): the formulae, definitions and observations the ESA
// expects, one section per syllabus unit. Hand-edited, not generated.
//
// Formulae use Unicode sub- and superscripts so they render the same everywhere
// and never depend on the formula heuristics in chem.js. The qualitative
// analysis tables are transcribed from the official 2023 data booklet
// (NIS/G12/CHE/QAD); the IR and NMR ranges are typical values and the booklet
// in the exam is authoritative.
//
// Each item: t = term, f = formula or equation (optional), d = the definition
// or the thing examiners want, in the words they want it.
window.CHEMPREP_REFERENCE = [

  { id: 'values', title: 'Constants and values', area: 'physical', topic: 'moles', items: [
    { t: 'Avogadro constant', f: 'L = 6.022 × 10²³ mol⁻¹', d: 'The number of particles in one mole. Number of particles = n × L.' },
    { t: 'Gas constant', f: 'R = 8.31 J K⁻¹ mol⁻¹', d: 'Used in pV = nRT and the Arrhenius equation.' },
    { t: 'Faraday constant', f: 'F = 96 500 C mol⁻¹', d: 'Charge on one mole of electrons; F = L × e, with e = 1.60 × 10⁻¹⁹ C.' },
    { t: 'Molar gas volume', f: '24.0 dm³ mol⁻¹ at r.t.p. (298 K, 101 kPa); 22.4 dm³ mol⁻¹ at s.t.p. (273 K, 101 kPa)', d: 'Check which the question gives you. Otherwise use pV = nRT.' },
    { t: 'Ionic product of water', f: 'Kw = [H⁺][OH⁻] = 1.00 × 10⁻¹⁴ mol² dm⁻⁶ at 298 K', d: 'Rises with temperature, so pure water is below pH 7 when hot but still neutral.' },
    { t: 'Specific heat capacity of water', f: 'c = 4.18 J g⁻¹ K⁻¹', d: 'Assume the solution has the density and heat capacity of water in calorimetry.' },
    { t: 'Temperature', f: 'T / K = θ / °C + 273', d: 'Every gas law, entropy and Gibbs calculation needs kelvin.' },
    { t: 'Pressure', f: '1 atm = 101 kPa = 1.01 × 10⁵ Pa', d: 'pV = nRT needs Pa and m³ (1 cm³ = 10⁻⁶ m³, 1 dm³ = 10⁻³ m³).' },
    { t: 'Planck', f: 'E = hν, c = νλ, h = 6.63 × 10⁻³⁴ J s', d: 'Energy of the photon absorbed when a d electron is promoted in a transition metal complex.' },
    { t: 'Natural log of 2', f: 'ln 2 = 0.693', d: 'First-order half-life t½ = 0.693 / k.' }
  ]},

  { id: 'atomic', title: 'Atomic structure', area: 'physical', topic: 'atomic-structure', items: [
    { t: 'Relative atomic mass, Ar', f: 'Ar = Σ(isotopic mass × % abundance) / 100', d: 'The weighted mean mass of an atom of an element, compared with one twelfth of the mass of an atom of carbon-12 (that is, in unified atomic mass units). Weighted mean because it averages the isotopes by their abundance.' },
    { t: 'Unified atomic mass unit, u', f: '1 u = 1/12 of the mass of one atom of carbon-12', d: 'The standard every relative mass is measured against: on this scale one carbon-12 atom has a mass of exactly 12 u.' },
    { t: 'Relative isotopic mass', d: 'The mass of one atom of an isotope relative to one twelfth of the mass of one atom of carbon-12.' },
    { t: 'Relative molecular mass, Mr', d: 'The weighted mean mass of a molecule, compared with one twelfth of the mass of an atom of carbon-12. Found by adding the Ar values in the molecular formula. In a mass spectrum it is the m/z of the molecular ion peak M⁺, the peak of highest m/z apart from M+1 and M+2.' },
    { t: 'Relative formula mass', d: 'The same idea for an ionic compound, which has no molecules: the weighted mean mass of one formula unit (NaCl, MgCl₂) compared with one twelfth of the mass of an atom of carbon-12.' },
    { t: 'Isotopes', d: 'Atoms of the same element, so the same number of protons, with different numbers of neutrons. Same chemical properties because they have the same electron configuration; different physical properties such as mass and density.' },
    { t: 'Subatomic particles', d: 'Proton: relative mass 1, charge +1. Neutron: 1, 0. Electron: 1/1836, −1. Proton (atomic) number Z; nucleon (mass) number A = protons + neutrons.' },
    { t: 'Mass spectrometer', d: 'Vaporisation, then ionisation by an electron gun (M + e⁻ → M⁺ + 2e⁻), acceleration in an electric field, deflection in a magnetic field (lighter ions and more highly charged ions deflect more), detection. Peak height gives abundance.' }
  ]},

  { id: 'electrons', title: 'Electrons and ionisation', area: 'physical', topic: 'electron-config', items: [
    { t: 'First ionisation energy', f: 'X(g) → X⁺(g) + e⁻', d: 'The energy required to remove one electron from each atom in one mole of gaseous atoms of an element, forming one mole of gaseous 1+ ions. State symbols (g) and "one mole" earn the marks.' },
    { t: 'Second ionisation energy', f: 'X⁺(g) → X²⁺(g) + e⁻', d: 'Successive ionisation energies always increase because each electron is removed from a more positive ion. A large jump means the next electron comes from a shell closer to the nucleus: the number of electrons removed before the jump is the group number.' },
    { t: 'Factors that decide ionisation energy', d: 'Nuclear charge (more protons, higher IE), distance of the electron from the nucleus (further, lower IE), shielding by inner shells (more, lower IE). Use all three in an explanation.' },
    { t: 'Trends', d: 'Across a period IE rises: nuclear charge increases, same shell, similar shielding. Down a group it falls: extra shells, more shielding, outweighing the nuclear charge. Dips across period 3: Al below Mg because the 3p electron is higher in energy than 3s; S below P because the paired 3p electrons repel.' },
    { t: 'Filling order', f: '1s 2s 2p 3s 3p 4s 3d 4p', d: 'Subshell capacities s 2, p 6, d 10, f 14. 4s fills before 3d but is emptied first, so transition metal ions lose their 4s electrons first. Exceptions: Cr [Ar] 3d⁵ 4s¹ and Cu [Ar] 3d¹⁰ 4s¹.' },
    { t: 'Orbital rules', d: 'Aufbau: lowest energy orbitals fill first. Pauli: an orbital holds at most two electrons, with opposite spins. Hund: orbitals of equal energy fill singly before any pairs up.' },
    { t: 'Orbital shapes', d: 's orbitals are spherical; p orbitals are dumbbell shaped, three per subshell at right angles (px, py, pz). Every shell has one s subshell; the second shell onward has p; the third onward has d.' }
  ]},

  { id: 'bonding', title: 'Bonding and structure', area: 'physical', topic: 'bonding', items: [
    { t: 'Ionic bond', d: 'The electrostatic attraction between oppositely charged ions. Giant ionic lattice: high melting point, conducts only when molten or dissolved, often soluble in water.' },
    { t: 'Covalent bond', d: 'A shared pair of electrons; the electrostatic attraction between the two nuclei and the shared pair.' },
    { t: 'Dative (co-ordinate) bond', d: 'A covalent bond in which both electrons come from the same atom. Examples: NH₄⁺, H₃O⁺, Al₂Cl₆, BF₃NH₃ (NH₃ donates, BF₃ accepts), every ligand in a complex ion.' },
    { t: 'Metallic bond', d: 'The electrostatic attraction between the lattice of positive metal ions and the delocalised electrons. Say delocalised electrons, never a sea of electrons: mark schemes reject the phrase. Strength rises with the charge on the ion and the number of delocalised electrons (Na < Mg < Al).' },
    { t: 'Electronegativity', d: 'The power of an atom to attract electrons to itself (the Cambridge A level wording; in a covalent bond, the bonding pair). Increases across a period and up a group; fluorine is highest. A difference gives a polar bond; a symmetrical molecule can still be non-polar (CO₂, CCl₄).' },
    { t: 'Sigma and pi bonds', d: 'σ: end-on overlap of orbitals along the bond axis. π: sideways overlap of p orbitals, electron density above and below the axis, weaker than σ. Single bond 1σ; double 1σ + 1π; triple 1σ + 2π.' },
    { t: 'Hybridisation', d: 'sp³: four hybrid orbitals, tetrahedral, 109.5° (alkanes, CH₄, NH₃, H₂O). sp²: three, trigonal planar, 120° (alkenes, benzene, BF₃). sp: two, linear, 180° (alkynes, CO₂, BeCl₂).' },
    { t: 'VSEPR', d: 'Electron pairs around the central atom repel and take up positions as far apart as possible. Repulsion: lone pair–lone pair > lone pair–bond pair > bond pair–bond pair, so each lone pair closes the angle by about 2.5°.' },
    { t: 'Shapes and angles', d: '2 bonding pairs: linear 180° (CO₂, BeCl₂). 3: trigonal planar 120° (BF₃, SO₃, AlCl₃). 4: tetrahedral 109.5° (CH₄, NH₄⁺, SO₄²⁻). 3 + 1 lone pair: trigonal pyramidal 107° (NH₃). 2 + 2 lone pairs: bent 104.5° (H₂O). 5: trigonal bipyramidal 120° and 90° (PCl₅). 6: octahedral 90° (SF₆, most complexes).' },
    { t: 'Instantaneous dipole–induced dipole forces', d: 'Also called London forces or van der Waals\' forces, present between all molecules. Uneven electron distribution gives one molecule an instantaneous dipole, which induces a dipole in a neighbouring molecule. Stronger with more electrons and more points of contact, so boiling points rise down group 17 and with chain length, and fall with branching.' },
    { t: 'Permanent dipole–dipole forces', d: 'Between polar molecules (HCl, CH₃COCH₃). Stronger than London forces of similar size.' },
    { t: 'Hydrogen bonding', d: 'A hydrogen atom covalently bonded to a highly electronegative N, O or F atom carries a large δ+ charge and is attracted to a lone pair on an N, O or F atom of another molecule. The strongest intermolecular force. Explains the high boiling points of H₂O, NH₃ and HF, alcohols and amines, ice being less dense than water, and solubility in water.' },
    { t: 'Structure types', d: 'Giant ionic (NaCl); giant covalent (diamond, graphite, SiO₂: very high melting point, insoluble; graphite conducts through delocalised electrons); giant metallic; simple molecular (I₂, CO₂, most organic compounds: low melting point because only weak intermolecular forces are overcome, molecules stay intact).' },
    { t: 'Bond energy', d: 'The energy required to break one mole of a particular covalent bond in the gaseous state. Some values are exact (H–H, Cl–Cl); most are averages over many compounds (C–H). Bond breaking is endothermic, bond forming exothermic.' },
    { t: 'Bond length', d: 'The internuclear distance of two covalently bonded atoms. Shorter bonds are generally stronger: C≡C < C=C < C–C in length.' }
  ]},

  { id: 'moles', title: 'Moles and stoichiometry', area: 'physical', topic: 'moles', items: [
    { t: 'Amount of substance', f: 'n = m / M', d: 'One mole is the amount of substance containing 6.022 × 10²³ particles (the Avogadro constant). n in mol, mass m in g, molar mass M in g mol⁻¹.' },
    { t: 'Solutions', f: 'n = c × V', d: 'c in mol dm⁻³, V in dm³ (cm³ ÷ 1000). Concentration in g dm⁻³ = c × M.' },
    { t: 'Gases', f: 'pV = nRT', d: 'p in Pa, V in m³, T in K, R = 8.31 J K⁻¹ mol⁻¹. At room temperature and pressure n = V / 24.0 with V in dm³.' },
    { t: 'Empirical formula', d: 'For each element divide the mass or percentage by Ar, divide every result by the smallest, multiply to whole numbers. Molecular formula = empirical formula × (Mr ÷ empirical formula mass).' },
    { t: 'Percentage yield', f: '% yield = actual mass of product / theoretical mass × 100', d: 'Theoretical mass comes from the limiting reagent through the balanced equation.' },
    { t: 'Atom economy', f: '% atom economy = Mr of desired product / sum of Mr of all reactants × 100', d: 'Addition reactions are 100 %; substitution and elimination lose atoms to by-products.' },
    { t: 'Limiting reagent', d: 'The reactant that is completely used up; it fixes the amount of product. Compare moles available with moles required by the equation.' },
    { t: 'Titration', f: 'c₁V₁ / a = c₂V₂ / b', d: 'a and b are the coefficients in the equation. Work in moles: n of the known solution, ratio, then n of the unknown, then c = n / V.' },
    { t: 'Water of crystallisation', d: 'Mass lost on heating is water: n(H₂O) = mass ÷ 18.0. Divide by n(anhydrous salt) to get x in MgSO₄·xH₂O.' },
    { t: 'Ionic equations', d: 'Write the full equation, split soluble strong electrolytes into ions, cancel spectator ions. Acid + alkali: H⁺(aq) + OH⁻(aq) → H₂O(l). Precipitation: Ag⁺(aq) + Cl⁻(aq) → AgCl(s).' }
  ]},

  { id: 'periodicity', title: 'Periodicity', area: 'physical', topic: 'periodicity', items: [
    { t: 'Periodicity', d: 'The repeating pattern of physical and chemical properties across each period.' },
    { t: 'Atomic radius', d: 'Decreases across a period (nuclear charge rises, same shielding, outer electrons attracted more strongly to the nucleus). Increases down a group (more shells). Cations are smaller than their atoms, anions larger.' },
    { t: 'Melting points across period 3', d: 'Na < Mg < Al: metallic bonding strengthens as the ion charge and number of delocalised electrons rise. Si highest: giant covalent. P₄, S₈, Cl₂, Ar: simple molecular, low, ordered by London forces so S₈ > P₄ > Cl₂ > Ar.' },
    { t: 'Electrical conductivity', d: 'Na, Mg, Al conduct (delocalised electrons, increasing Na to Al). Si is a semiconductor. P, S, Cl, Ar do not conduct.' },
    { t: 'Period 3 elements with oxygen', f: '4Na + O₂ → 2Na₂O; 2Mg + O₂ → 2MgO; 4Al + 3O₂ → 2Al₂O₃; Si + O₂ → SiO₂; P₄ + 5O₂ → P₄O₁₀; S + O₂ → SO₂', d: 'Na burns yellow, Mg bright white, S blue.' },
    { t: 'Oxides with water', d: 'Na₂O + H₂O → 2NaOH (pH 13–14). MgO + H₂O → Mg(OH)₂, sparingly (pH 9). Al₂O₃ and SiO₂ insoluble (pH 7). P₄O₁₀ + 6H₂O → 4H₃PO₄ (pH 1–2). SO₂ + H₂O → H₂SO₃; SO₃ + H₂O → H₂SO₄ (pH 1).' },
    { t: 'Oxides: acid–base character', d: 'Na₂O and MgO basic (react with acids). Al₂O₃ amphoteric: Al₂O₃ + 6HCl → 2AlCl₃ + 3H₂O and Al₂O₃ + 2NaOH + 3H₂O → 2NaAl(OH)₄. SiO₂, P₄O₁₀, SO₂, SO₃ acidic: SiO₂ + 2NaOH → Na₂SiO₃ + H₂O (hot, concentrated).' },
    { t: 'Chlorides with water', d: 'NaCl and MgCl₂ dissolve (MgCl₂ slightly acidic, pH 6.5). AlCl₃ hydrolyses with fumes of HCl, pH 3. SiCl₄ + 2H₂O → SiO₂ + 4HCl, pH 2. PCl₅ + 4H₂O → H₃PO₄ + 5HCl, pH 2. Trend from ionic to covalent, hydrolysed, chlorides.' },
    { t: 'Blocks of the Periodic Table', d: 'An element belongs to the block of the subshell that its highest-energy electron occupies. s block: groups 1 and 2 (and helium). p block: groups 13 to 18. d block: the transition metals between groups 2 and 13. f block: the lanthanides and actinides. The Aufbau filling order explains the shape of the table: the period lengths 2, 8, 8, 18, 18, 32 match the electrons held by the s, p, d and f subshells filled in each period.' },
    { t: 'Forms of the Periodic Table', d: 'Mendeleev (1869) arranged the elements by atomic mass and grouped them by similar properties. He left gaps and predicted the properties of undiscovered elements such as germanium (eka-silicon) and gallium (eka-aluminium), and swapped tellurium and iodine to keep the groups right. The modern table is arranged by proton (atomic) number, which removes those anomalies (Ar before K, Te before I). Elements in a group share the same outer electron configuration; elements in a period have the same number of shells.' },
    { t: 'Trends down group 1', f: '2M + 2H₂O → 2MOH + H₂', d: 'Reactivity increases down the group: atomic radius and shielding increase, so the single outer electron is lost more easily (first ionisation energy falls). Melting points fall because the larger ions attract the delocalised electrons less strongly. With water, lithium fizzes steadily, sodium melts into a ball and moves about, and potassium ignites with a lilac flame. Contrast group 17, where reactivity decreases down the group because the atoms gain electrons instead of losing them.' }
  ]},

  { id: 'energetics', title: 'Energetics and entropy', area: 'physical', topic: 'energetics', items: [
    { t: 'Enthalpy change, ΔH', d: 'The heat energy change of a reaction carried out at constant pressure, in kJ mol⁻¹. Negative for exothermic reactions (heat given out, products lower in energy than reactants), positive for endothermic.' },
    { t: 'Standard conditions', f: '298 K and 101 kPa', d: 'The values Cambridge A level uses (shown by ⦵); IUPAC uses 100 kPa. Solutions at 1 mol dm⁻³, substances in their standard states. A standard enthalpy change, ΔH⦵, is one measured under these conditions.' },
    { t: 'Standard enthalpy change of formation, ΔH°f', d: 'The enthalpy change when one mole of a compound is formed from its elements in their standard states under standard conditions. ΔH°f of an element in its standard state is zero.' },
    { t: 'Standard enthalpy change of combustion, ΔH°c', d: 'The enthalpy change when one mole of a substance is burnt in an excess of oxygen under standard conditions. Always exothermic.' },
    { t: 'Standard enthalpy change of neutralisation', d: 'The enthalpy change when one mole of water is formed by the reaction of an acid with an alkali under standard conditions. About −57 kJ mol⁻¹ for any strong acid with any strong base; less exothermic for weak acids because some energy goes into dissociating them.' },
    { t: 'Standard enthalpy change of atomisation', f: '½Cl₂(g) → Cl(g); Na(s) → Na(g)', d: 'The enthalpy change when one mole of gaseous atoms is formed from the element in its standard state. Always endothermic.' },
    { t: 'Lattice enthalpy (of formation)', f: 'Na⁺(g) + Cl⁻(g) → NaCl(s)', d: 'The enthalpy change when one mole of an ionic solid is formed from its gaseous ions. Always exothermic; more exothermic for small, highly charged ions (high charge density). Some syllabuses define the reverse, lattice dissociation, as positive: read the question.' },
    { t: 'First electron affinity', f: 'Cl(g) + e⁻ → Cl⁻(g)', d: 'The enthalpy change when one electron is added to each atom in one mole of gaseous atoms, forming one mole of gaseous 1− ions. Exothermic. The second electron affinity (O⁻ → O²⁻) is endothermic because an electron is added to a negative ion.' },
    { t: 'Enthalpy of hydration and solution', f: 'ΔH⦵sol = −ΔH⦵latt + Σ ΔH⦵hyd', d: 'Hydration: the enthalpy change when one mole of a specified gaseous ion dissolves in sufficient water to form a very dilute solution (always exothermic, larger for small, highly charged ions). Solution: the enthalpy change when one mole of an ionic solid dissolves in sufficient water to form a very dilute solution.' },
    { t: 'Calorimetry', f: 'q = m c ΔT;   ΔH = −q / n', d: 'm is the mass of water or solution heated (g), c = 4.18 J g⁻¹ K⁻¹, ΔT the temperature rise. Divide by moles of the limiting reactant, convert J to kJ, and give the sign: temperature rise means exothermic, negative ΔH.' },
    { t: 'Hess\'s law', f: 'ΔH°r = Σ ΔH°f(products) − Σ ΔH°f(reactants);   ΔH°r = Σ ΔH°c(reactants) − Σ ΔH°c(products)', d: 'The total enthalpy change of a reaction is independent of the route taken. Multiply each value by its coefficient in the equation.' },
    { t: 'Bond enthalpy calculations', f: 'ΔH = Σ(bonds broken) − Σ(bonds formed)', d: 'Only for gaseous species. Results are approximate because bond enthalpies are averages.' },
    { t: 'Born–Haber cycle', f: 'ΔH°f(NaCl) = ΔH°at(Na) + IE₁(Na) + ΔH°at(Cl) + EA₁(Cl) + LE', d: 'For MgCl₂ add the second ionisation energy and use 2 × ΔH°at(Cl) and 2 × EA. Draw levels for each step; the lattice enthalpy arrow comes down from the gaseous ions to the solid.' },
    { t: 'Entropy, S', f: 'ΔS⦵ = Σ S⦵(products) − Σ S⦵(reactants)', d: 'The number of possible arrangements of the particles and their energy in a given system (the Cambridge definition; "disorder" is the informal idea). J K⁻¹ mol⁻¹. Increases on melting, boiling, dissolving, on heating, and when the number of gas molecules increases. Predict the sign from the gas count.' },
    { t: 'Gibbs free energy', f: 'ΔG = ΔH − TΔS', d: 'T in kelvin and ΔS in kJ K⁻¹ mol⁻¹ (divide J by 1000). A reaction is feasible when ΔG < 0. When ΔH and ΔS are both positive the reaction becomes feasible above T = ΔH / ΔS; both negative, below it. Feasible does not mean fast: the activation energy may be too high.' },
    { t: 'Exothermic and endothermic', d: 'Exothermic: heat released to the surroundings, ΔH negative, products lower in energy. Endothermic: heat absorbed, ΔH positive. Activation energy is the minimum energy colliding particles need to react; on a profile it is measured from reactants to the peak.' }
  ]},

  { id: 'kinetics', title: 'Reaction kinetics', area: 'physical', topic: 'kinetics', items: [
    { t: 'Rate of reaction', d: 'The change in concentration of a reactant or product per unit time, mol dm⁻³ s⁻¹. On a concentration–time graph the rate is the gradient of the tangent.' },
    { t: 'Rate equation', f: 'rate = k [A]ᵐ [B]ⁿ', d: 'm and n are the orders with respect to A and B, found only by experiment, never from the equation. Overall order = m + n.' },
    { t: 'Order of reaction', d: 'The power to which the concentration of a species is raised in the rate equation. The overall order is the sum of the individual orders.' },
    { t: 'Rate constant, k', d: 'The proportionality constant in the rate equation. It is constant at a given temperature, increases with temperature, and is larger with a catalyst; its units depend on the overall order.' },
    { t: 'Units of k', d: 'Zero order: mol dm⁻³ s⁻¹. First order: s⁻¹. Second order: dm³ mol⁻¹ s⁻¹. Third order: dm⁶ mol⁻² s⁻¹. Rearrange k = rate / concentrations and cancel.' },
    { t: 'Finding orders from initial rates', d: 'Change one concentration at a time. Doubling it leaves the rate unchanged: zero order. Doubles the rate: first order. Quadruples it: second order.' },
    { t: 'Orders from graphs', d: 'Rate against concentration: horizontal line zero order, straight line through the origin first order, curve second order. Concentration against time: straight line zero order; curve with a constant half-life first order; curve with increasing half-lives second order.' },
    { t: 'Half-life', f: 't½ = ln 2 / k = 0.693 / k', d: 'Time for the concentration to fall to half. Constant for a first-order reaction and independent of the starting concentration.' },
    { t: 'Rate-determining step', d: 'The slowest step of a mechanism. Only species that take part in it, or in steps before it, appear in the rate equation; their orders equal the number of times they appear.' },
    { t: 'Arrhenius equation', f: 'k = A e^(−Ea / RT);   ln k = ln A − Ea / (RT)', d: 'A plot of ln k against 1/T is a straight line with gradient −Ea / R and intercept ln A. Ea in J mol⁻¹ when R = 8.31.' },
    { t: 'Maxwell–Boltzmann distribution', d: 'The spread of molecular energies in a gas. Starts at the origin (no molecules with zero energy), peaks at the most probable energy, never touches the axis at high energy; area under the curve = number of molecules. At a higher temperature the peak moves right and lower, the curve broadens, and many more molecules have energy at or above Ea. A catalyst does not change the curve; it lowers Ea so a larger fraction can react.' },
    { t: 'Catalyst', d: 'A substance that increases the rate by providing an alternative reaction pathway with a lower activation energy, and is chemically unchanged at the end.' },
    { t: 'Homogeneous and heterogeneous catalysis', d: 'Homogeneous: same phase as the reactants, forms an intermediate (H⁺ in esterification, Cl• in ozone depletion, Fe²⁺/Fe³⁺ in the peroxodisulfate–iodide reaction). Heterogeneous: different phase, usually a solid surface: reactants adsorb onto active sites, bonds weaken, products desorb (Fe in Haber, V₂O₅ in Contact, Ni in hydrogenation, Pt/Pd/Rh in catalytic converters).' },
    { t: 'Collision theory', d: 'Particles react only when they collide with energy at least equal to the activation energy and in the correct orientation. Higher concentration or pressure: more particles per unit volume, so a higher collision frequency. Higher temperature: particles have more kinetic energy, so a greater proportion of collisions have energy at or above Ea (the main effect) and collisions are also more frequent. Smaller particle size: larger surface area.' },
    { t: 'Activation energy, Ea', d: 'The minimum energy required for a collision to be effective, that is, to lead to a reaction. On a reaction pathway diagram it is measured from the reactants up to the peak.' },
    { t: 'Enzymes', d: 'Protein catalysts with an active site that fits a specific substrate. Inhibitors bind the active site (competitive) or elsewhere; temperature or pH beyond the optimum denatures the enzyme.' }
  ]},

  { id: 'equilibria', title: 'Chemical equilibria', area: 'physical', topic: 'equilibria', items: [
    { t: 'Dynamic equilibrium', d: 'In a closed system the forward and reverse reactions proceed at equal rates, so the concentrations of reactants and products stay constant.' },
    { t: 'Equilibrium constant Kc', f: 'aA + bB ⇌ cC + dD:   Kc = [C]ᶜ [D]ᵈ / [A]ᵃ [B]ᵇ', d: 'Equilibrium concentrations in mol dm⁻³. Units depend on the expression; a pure solid or the solvent is left out. Use an ICE table (initial, change, equilibrium) and divide by the volume before substituting.' },
    { t: 'Equilibrium constant Kp', f: 'Kp = p(C)ᶜ p(D)ᵈ / p(A)ᵃ p(B)ᵇ;   p(A) = x(A) × P', d: 'Partial pressure = mole fraction × total pressure; mole fraction = moles of that gas ÷ total moles of gas. Units in Pa or atm to the net power.' },
    { t: 'Le Chatelier\'s principle', d: 'If a change is made to a system at dynamic equilibrium, the position of equilibrium moves to minimise this change. Raise the temperature: shifts in the endothermic direction. Raise the pressure: shifts to the side with fewer moles of gas. Add a reactant or remove a product: shifts right. Catalyst: no change in position, only reached faster.' },
    { t: 'What changes K', d: 'Only temperature. For an exothermic forward reaction K decreases as temperature rises; for endothermic it increases. Concentration, pressure and catalysts change the position, not K. A large K means the equilibrium lies to the right.' },
    { t: 'Haber process', f: 'N₂(g) + 3H₂(g) ⇌ 2NH₃(g)   ΔH = −92 kJ mol⁻¹', d: '400–450 °C, 200 atm, iron catalyst. Low temperature favours yield but is too slow; high pressure favours yield but costs money and safety; the catalyst lets a moderate temperature work. Ammonia is condensed out and unreacted gases recycled.' },
    { t: 'Contact process', f: '2SO₂(g) + O₂(g) ⇌ 2SO₃(g)   ΔH = −196 kJ mol⁻¹', d: '450 °C, 1–2 atm, vanadium(V) oxide. High pressure is unnecessary because the yield is already about 97 %.' }
  ]},

  { id: 'acids', title: 'Acids, bases and buffers', area: 'physical', topic: 'acids-bases', items: [
    { t: 'Brønsted–Lowry', d: 'An acid is a proton donor; a base is a proton acceptor. A conjugate pair differs by one H⁺: CH₃COOH / CH₃COO⁻, NH₄⁺ / NH₃. Water is amphiprotic.' },
    { t: 'Strong and weak', d: 'Strong: fully dissociated in water (HCl, HNO₃, H₂SO₄, NaOH, KOH). Weak: partially dissociated, equilibrium lies to the left (CH₃COOH, HCN, NH₃). Strength is not concentration.' },
    { t: 'pH', f: 'pH = −log₁₀[H⁺];   [H⁺] = 10⁻ᵖᴴ', d: 'One pH unit is a factor of ten in [H⁺]. Give pH to two decimal places.' },
    { t: 'pH of a strong base', f: '[H⁺] = Kw / [OH⁻];   pH = 14 + log₁₀[OH⁻] at 298 K', d: '[OH⁻] equals the base concentration for NaOH and twice it for Ba(OH)₂.' },
    { t: 'Acid dissociation constant', f: 'Ka = [H⁺][A⁻] / [HA];   pKa = −log₁₀ Ka', d: 'For a weak acid on its own [H⁺] = [A⁻] and [HA] ≈ c, so [H⁺] = √(Ka × c). Lower pKa, stronger acid.' },
    { t: 'Base dissociation constant', f: 'Kb = [BH⁺][OH⁻] / [B];   Ka × Kb = Kw', d: 'For a weak base alone [OH⁻] = √(Kb × c), then pH through Kw.' },
    { t: 'Buffer solution', d: 'A solution that minimises (resists) changes in pH when small amounts of acid or alkali are added. Acidic buffer: a weak acid and its salt (CH₃COOH and CH₃COONa). Basic buffer: a weak base and its salt (NH₃ and NH₄Cl). Made by mixing, or by partly neutralising the weak acid with strong base.' },
    { t: 'How a buffer works', f: 'H⁺ + A⁻ → HA;   OH⁻ + HA → A⁻ + H₂O', d: 'Large reservoirs of both HA and A⁻. Added H⁺ is removed by A⁻, added OH⁻ by HA, so the ratio [A⁻]/[HA] and hence the pH barely change.' },
    { t: 'Buffer pH', f: '[H⁺] = Ka × [HA] / [A⁻];   pH = pKa + log₁₀([A⁻] / [HA])', d: 'pH = pKa when [HA] = [A⁻], which is the half-neutralisation point and the point of greatest buffering capacity.' },
    { t: 'Blood buffer', f: 'H₂CO₃ ⇌ H⁺ + HCO₃⁻', d: 'Keeps blood at pH 7.4. Added acid: HCO₃⁻ + H⁺ → H₂CO₃ (removed as CO₂ in the lungs). Added base: H₂CO₃ + OH⁻ → HCO₃⁻ + H₂O.' },
    { t: 'Titration curves', d: 'Strong acid–strong base: starts pH 1, near-vertical from about 3 to 11, equivalence pH 7. Weak acid–strong base: starts about pH 3, buffer region, half-neutralisation at pH = pKa, vertical section from about 7 to 11, equivalence above 7 (about 9). Strong acid–weak base: vertical from about 3 to 7, equivalence below 7 (about 5). Weak–weak: no vertical section, no suitable indicator. A diprotic acid such as propanedioic acid shows two vertical sections.' },
    { t: 'Indicators', d: 'Weak acids whose acid and conjugate base differ in colour; they change over about two pH units around their pKind. Methyl orange: range 3.1–4.4, red in acid, yellow in alkali; suits strong acid–weak base. Phenolphthalein: range 8.3–10.0, colourless in acid, pink in alkali; suits weak acid–strong base. Either suits strong–strong. Choose the indicator whose range lies inside the vertical section.' },
    { t: 'Equivalence and end point', d: 'Equivalence point: the acid and base have reacted in the exact ratio of the equation. End point: the indicator changes colour. A good indicator makes them coincide.' },
    { t: 'Neutralisation enthalpy and weak acids', d: 'Weak acid neutralisations are less exothermic than −57 kJ mol⁻¹ because energy is used to dissociate the acid first.' },
    { t: 'Amphoteric', d: 'Reacts as both an acid and a base: Al(OH)₃, Zn(OH)₂, Al₂O₃, amino acids. Amphiprotic: can both donate and accept a proton: H₂O, HCO₃⁻, HSO₄⁻.' }
  ]},

  { id: 'electro', title: 'Electrochemistry', area: 'physical', topic: 'electrochemistry', items: [
    { t: 'Oxidation and reduction', d: 'Oxidation is loss of electrons, an increase in oxidation number. Reduction is gain of electrons, a decrease. An oxidising agent is itself reduced; a reducing agent is itself oxidised.' },
    { t: 'Oxidation number rules', d: 'Uncombined element 0. F always −1. O −2, except peroxides −1 and OF₂ +2. H +1, except metal hydrides −1. Group 1 +1, group 2 +2, Al +3. Oxidation numbers sum to the charge on the species. Roman numerals in a name give the oxidation state: iron(III), manganate(VII), chlorate(V).' },
    { t: 'Balancing half-equations in acid', d: 'Balance the atoms other than O and H, balance O with H₂O, balance H with H⁺, balance charge with e⁻. Multiply the two half-equations so the electrons cancel, then add. In alkali add OH⁻ to both sides to remove H⁺.' },
    { t: 'Disproportionation', f: 'Cl₂ + H₂O ⇌ HCl + HClO;   2Cu⁺ → Cu + Cu²⁺', d: 'One species is simultaneously oxidised and reduced.' },
    { t: 'Standard electrode potential, E°', d: 'The standard electrode (reduction) potential: the potential of a half-cell measured against the standard hydrogen electrode under standard conditions: 298 K, gases at 101 kPa, ions at 1.00 mol dm⁻³. The hydrogen electrode (Pt, H₂ at 101 kPa, 1.00 mol dm⁻³ H⁺) is defined as 0.00 V. Metals act as their own electrode; ion–ion systems need an inert platinum electrode. A salt bridge (KNO₃ or KCl in agar) completes the circuit and a high-resistance voltmeter measures the emf.' },
    { t: 'Cell emf', f: 'E°cell = E°(positive electrode) − E°(negative electrode) = E°(more positive) − E°(less positive)', d: 'The half-cell with the more positive E° is reduced (cathode, positive terminal); the other is oxidised (anode, negative). Reaction is feasible when E°cell is positive. Electrons flow through the external wire from the negative electrode to the positive.' },
    { t: 'Reading the electrochemical series', d: 'The more positive the E°, the stronger the oxidising agent on the left of the half-equation (F₂, MnO₄⁻, Cl₂). The more negative, the stronger the reducing agent on the right (Li, K, Na, Mg, Zn). A species on the left will oxidise any species on the right of a half-equation with a lower E°.' },
    { t: 'Cell diagram', f: 'Zn(s) | Zn²⁺(aq) || Cu²⁺(aq) | Cu(s)   E°cell = +0.34 − (−0.76) = +1.10 V', d: 'Oxidation on the left, reduction on the right, the double line is the salt bridge. E°cell = E°right − E°left.' },
    { t: 'Non-standard conditions', f: 'E = E° + (0.059 / z) log₁₀([oxidised] / [reduced]) at 298 K', d: 'Raising the concentration of the oxidised species (the left of the half-equation) makes E more positive; diluting it makes E less positive. Qualitatively, apply Le Chatelier to the half-equation.' },
    { t: 'Free energy and emf', f: 'ΔG° = −n F E°cell', d: 'n is the number of electrons transferred in the balanced equation. Positive E°cell means negative ΔG°, a feasible reaction.' },
    { t: 'Electrolysis', d: 'Cathode (negative): cations gain electrons, reduced. Anode (positive): anions lose electrons, oxidised. Molten salt: the metal and the non-metal. Aqueous: at the cathode the less reactive of the metal and hydrogen (2H₂O + 2e⁻ → H₂ + 2OH⁻ for reactive metals); at the anode a concentrated halide gives the halogen, otherwise oxygen (4OH⁻ → O₂ + 2H₂O + 4e⁻). Inert electrodes are graphite or platinum; a copper anode dissolves (purification of copper).' },
    { t: 'Faraday\'s laws', f: 'Q = I t;   n(e⁻) = Q / F;   F = 96 500 C mol⁻¹', d: 'Charge in coulombs from current in amperes and time in seconds. Moles of electrons, then use the half-equation (Cu²⁺ + 2e⁻ → Cu needs 2 mol of electrons per mole of copper). Mass = n × M; gas volume = n × 24.0 dm³.' },
    { t: 'Lead–acid and fuel cells', f: 'Pb + PbO₂ + 2H₂SO₄ ⇌ 2PbSO₄ + 2H₂O (discharge →, recharge ←)', d: 'Recharging reverses the discharge reactions. Hydrogen fuel cell: H₂ + ½O₂ → H₂O, E°cell = +1.23 V, water the only product; hydrogen storage and production are the drawbacks.' },
    { t: 'Commercial cells', d: 'Alkaline cell: zinc negative electrode, manganese(IV) oxide positive electrode, KOH electrolyte, about 1.5 V, not rechargeable. Lead–acid: Pb and PbO₂ in sulfuric acid, 2 V per cell, rechargeable. Lithium-ion: Li⁺ ions move through a non-aqueous electrolyte between a lithium cobalt oxide positive electrode and a graphite negative electrode, about 3.7 V, rechargeable and light. Charging uses an external supply to force the discharge reaction in reverse. Fuel cells need no recharging while fuel is supplied, but hydrogen is flammable, hard to store and mostly made from fossil fuels.' }
  ]},

  { id: 'group2', title: 'Group 2', area: 'inorganic', topic: 'group2', items: [
    { t: 'Trend in reactivity', d: 'Increases down the group: atomic radius rises and shielding increases, which outweighs the higher nuclear charge, so the two outer electrons are lost more easily (first and second ionisation energies fall).' },
    { t: 'With water', f: 'Mg + H₂O(g) → MgO + H₂;   Ca + 2H₂O(l) → Ca(OH)₂ + H₂', d: 'Magnesium reacts very slowly with cold water and quickly with steam to give the oxide. Calcium, strontium and barium react with cold water to give the hydroxide and hydrogen, faster down the group.' },
    { t: 'With oxygen and acids', f: '2M + O₂ → 2MO;   M + 2HCl → MCl₂ + H₂', d: 'All burn in oxygen to white ionic oxides. Magnesium burns with a bright white flame.' },
    { t: 'Oxides and hydroxides', f: 'MO + H₂O → M(OH)₂', d: 'Basic. MgO reacts barely; BaO vigorously. Hydroxides neutralise acids: Mg(OH)₂ + 2HCl → MgCl₂ + 2H₂O.' },
    { t: 'Solubility trends', d: 'Hydroxides become more soluble down the group: Mg(OH)₂ sparingly soluble, Ba(OH)₂ soluble (solutions become more alkaline). Sulfates become less soluble: MgSO₄ soluble, BaSO₄ insoluble, which is why Ba²⁺ is the test for sulfate and barium sulfate is safe as a barium meal.' },
    { t: 'Thermal stability of carbonates and nitrates', f: 'MCO₃ → MO + CO₂;   2M(NO₃)₂ → 2MO + 4NO₂ + O₂', d: 'Stability increases down the group. Smaller cations have a higher charge density, polarise the large anion more, weaken its C–O or N–O bonds, and so decompose at a lower temperature. MgCO₃ decomposes easily; BaCO₃ needs a very high temperature.' },
    { t: 'Uses', d: 'Ca(OH)₂ (slaked lime), CaO and CaCO₃ neutralise acidic soil and lakes; CaO and CaCO₃ also remove SO₂ from flue gases. Mg(OH)₂ is an antacid (milk of magnesia). CaCO₃ is limestone for cement. Acidified BaCl₂ solution is the test for sulfate ions (white precipitate of BaSO₄), and insoluble BaSO₄ is safe to swallow as a barium meal for X-ray imaging.' }
  ]},

  { id: 'group14', title: 'Group 14', area: 'inorganic', topic: 'group14', items: [
    { t: 'Trend in character', d: 'Carbon is a non-metal (diamond and graphite, giant covalent), silicon and germanium are metalloids, tin and lead are metals. Melting points fall from silicon to lead as the structure changes from giant covalent to metallic.' },
    { t: 'Oxidation states', d: '+4 and +2. The +4 state is the stable one at the top; the +2 state becomes more stable down the group (inert pair effect, the ns² electrons are less readily used in bonding). So Pb²⁺ compounds are common and ionic, PbO₂ is a strong oxidising agent (PbO₂ + 4HCl → PbCl₂ + Cl₂ + 2H₂O) and Sn²⁺ is a reducing agent (Sn²⁺ → Sn⁴⁺ + 2e⁻).' },
    { t: 'Tetrachlorides', f: 'SiCl₄ + 2H₂O → SiO₂ + 4HCl', d: 'All simple molecular, tetrahedral, volatile liquids. CCl₄ does not hydrolyse because carbon has no low-energy d orbitals to accept a lone pair from water. SiCl₄, GeCl₄ and SnCl₄ hydrolyse readily with fumes of HCl. PbCl₄ decomposes to PbCl₂ and Cl₂.' },
    { t: 'Oxides', d: 'CO₂: simple molecular gas, weakly acidic (with NaOH → Na₂CO₃). SiO₂: giant covalent, high melting point, acidic (hot concentrated NaOH → Na₂SiO₃). CO: neutral, reducing agent. GeO₂, SnO₂ and PbO₂ amphoteric, as are SnO and PbO.' },
    { t: 'Catenation', d: 'Carbon forms long chains because the C–C bond is strong (about 350 kJ mol⁻¹) and comparable to C–O and C–H; the M–M bond enthalpy falls down the group so Si–Si chains are short and unstable.' },
    { t: 'Occurrence and extraction', f: 'SiO₂ + 2C → Si + 2CO;   SnO₂ + 2C → Sn + 2CO;   2PbS + 3O₂ → 2PbO + 2SO₂, then PbO + C → Pb + CO', d: 'Carbon occurs as diamond, graphite and coal, and combined in carbonates, CO₂ and all living things. Silicon is the second most abundant element in the crust, as silica (sand, quartz) and silicates; silica is reduced with carbon in an electric furnace, and the silicon is purified further for electronics. Germanium is a by-product of zinc refining. Tin comes from cassiterite, SnO₂, reduced by carbon. Lead comes from galena, PbS, roasted in air to the oxide and then reduced by carbon; the SO₂ released must be captured.' },
    { t: 'Uses', d: 'Diamond: cutting tools. Graphite: electrodes and lubricant. Silicon: microchips and solar cells; silica makes glass. Germanium: semiconductors and optical fibres. Tin: coating steel cans, solder and bronze. Lead: lead–acid batteries and radiation shielding, now limited because lead is toxic.' }
  ]},

  { id: 'group17', title: 'Group 17', area: 'inorganic', topic: 'group17', items: [
    { t: 'Physical trends', d: 'Chlorine pale green gas, bromine red-brown liquid, iodine grey-black solid that sublimes to a purple vapour. Boiling point rises down the group: more electrons, stronger London forces. Electronegativity falls down the group.' },
    { t: 'Oxidising power', f: 'Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂;   Cl₂ + 2I⁻ → 2Cl⁻ + I₂;   Br₂ + 2I⁻ → 2Br⁻ + I₂', d: 'Decreases down the group: the added electron enters a shell further from the nucleus with more shielding, so it is attracted less strongly despite the higher nuclear charge. A halogen displaces any halide below it. Observations: bromine gives an orange solution, iodine a brown solution (purple in an organic solvent such as cyclohexane).' },
    { t: 'Test for halide ions', d: 'Acidify with dilute nitric acid (removes carbonate and hydroxide), add silver nitrate. Cl⁻: white precipitate, dissolves in dilute ammonia. Br⁻: cream precipitate, dissolves only in concentrated ammonia. I⁻: yellow precipitate, insoluble in concentrated ammonia.' },
    { t: 'Halides with concentrated sulfuric acid', d: 'Cl⁻: steamy fumes of HCl only; chloride cannot reduce H₂SO₄. Br⁻: HBr fumes, then orange Br₂ vapour and SO₂ (bromide reduces S from +6 to +4). I⁻: HI, then purple I₂, SO₂, yellow solid S and H₂S (bad-egg smell; iodide reduces S to +4, 0 and −2). Reducing power of halide ions increases down the group.' },
    { t: 'Chlorine and water', f: 'Cl₂ + H₂O ⇌ HCl + HClO', d: 'Disproportionation: chlorine goes from 0 to −1 and +1. Chloric(I) acid kills bacteria, so chlorine is used in water treatment. In sunlight: 2Cl₂ + 2H₂O → 4HCl + O₂.' },
    { t: 'Chlorine and sodium hydroxide', f: 'Cl₂ + 2NaOH → NaCl + NaClO + H₂O (cold, dilute);   3Cl₂ + 6NaOH → 5NaCl + NaClO₃ + 3H₂O (hot, concentrated)', d: 'Sodium chlorate(I) is bleach. Both are disproportionation reactions.' },
    { t: 'Chlorine in water treatment: benefits and risks', d: 'Chloric(I) acid, HClO, and ClO⁻ kill bacteria, preventing diseases such as cholera and typhoid, and keep working in the pipes. Risks: chlorine is a toxic gas, and it reacts with organic matter in the water to form chlorinated hydrocarbons such as trichloromethane, which may cause cancer. The benefit of safe drinking water far outweighs the small risk. Other uses of chlorine: PVC, bleach (NaClO), solvents and hydrochloric acid.' },
    { t: 'Hydrogen halides', d: 'Thermal stability decreases down the group as the H–X bond gets weaker and longer: HI decomposes on a hot wire, HCl does not. All except HF are strong acids in water; HF is weak because of the strong H–F bond and hydrogen bonding.' }
  ]},

  { id: 'nitrogen', title: 'Nitrogen and sulfur', area: 'inorganic', topic: 'nitrogen-sulfur', items: [
    { t: 'Why nitrogen is unreactive', d: 'The N≡N triple bond is very strong (about 944 kJ mol⁻¹) and the molecule is non-polar, so a large activation energy is needed.' },
    { t: 'Ammonia', f: 'NH₃ + H₂O ⇌ NH₄⁺ + OH⁻;   NH₃ + HCl → NH₄Cl', d: 'Weak base; the lone pair on nitrogen accepts a proton. Ammonium salts release ammonia when warmed with sodium hydroxide: NH₄⁺ + OH⁻ → NH₃ + H₂O. Test: ammonia turns damp red litmus blue and gives white fumes with HCl.' },
    { t: 'Nitric acid from ammonia', f: '4NH₃ + 5O₂ → 4NO + 6H₂O;   2NO + O₂ → 2NO₂;   4NO₂ + O₂ + 2H₂O → 4HNO₃', d: 'Ostwald process: platinum–rhodium catalyst, about 900 °C for the first step. Nitric acid makes fertilisers (NH₄NO₃) and explosives.' },
    { t: 'Oxides of nitrogen as pollutants', f: 'N₂ + O₂ → 2NO (in engines);   2NO + O₂ → 2NO₂', d: 'Formed at the high temperature inside engines. NO₂ dissolves in rain to give nitric acid (acid rain), forms photochemical smog, and catalyses the oxidation of SO₂ to SO₃. Catalytic converters remove them: 2NO + 2CO → N₂ + 2CO₂.' },
    { t: 'Sulfur dioxide and acid rain', f: 'SO₂ + H₂O → H₂SO₃;   2SO₂ + O₂ → 2SO₃;   SO₃ + H₂O → H₂SO₄', d: 'Formed when sulfur in fossil fuels burns. Removed from flue gases by calcium oxide or calcium carbonate: CaO + SO₂ → CaSO₃. Uses: food preservative (antioxidant and antibacterial) and bleaching.' },
    { t: 'Contact process', f: 'S + O₂ → SO₂;   2SO₂ + O₂ ⇌ 2SO₃;   SO₃ + H₂SO₄ → H₂S₂O₇;   H₂S₂O₇ + H₂O → 2H₂SO₄', d: 'Vanadium(V) oxide catalyst, 450 °C, 1–2 atm. SO₃ is absorbed in concentrated sulfuric acid, not water, because the direct reaction with water forms a corrosive mist.' },
    { t: 'Sulfuric acid', d: 'Dilute: a typical strong acid. Concentrated: a dehydrating agent (sugar, hydrated copper sulfate) and an oxidising agent (with Br⁻ and I⁻). Manufactured for fertilisers, detergents, paints and car batteries.' },
    { t: 'Fertilisers and eutrophication', d: 'Nitrate and ammonium fertilisers are very soluble and leach into rivers, causing algal blooms, oxygen depletion and the death of aquatic life.' },
    { t: 'Sulfur: occurrence and allotropy', d: 'Sulfur occurs as the element in volcanic regions and underground deposits; in sulfide ores (galena PbS, zinc blende ZnS, pyrite FeS₂); in sulfates such as gypsum, CaSO₄·2H₂O; and as H₂S and organic compounds in natural gas and crude oil, from which most sulfur is now recovered. Both main allotropes are built from S₈ crown-shaped rings: rhombic sulfur is stable below about 96 °C, monoclinic above it. Pouring molten sulfur into cold water gives plastic sulfur, long tangled chains that slowly turn back to rhombic.' },
    { t: 'Minimising the environmental impact', d: 'SO₂: remove sulfur from fuels before burning, scrub flue gases with CaO or CaCO₃ (flue gas desulfurisation), switch to low-sulfur fuels or renewables. NOₓ: catalytic converters and lower combustion temperatures. Nitrates: apply fertiliser in the right amount at the right time, not before heavy rain, and leave buffer strips beside rivers. Sulfuric acid plants absorb SO₃ efficiently and recycle unreacted SO₂, so little escapes.' }
  ]},

  { id: 'transition', title: 'Transition metals', area: 'inorganic', topic: 'transition-metals', items: [
    { t: 'Transition element', d: 'A d-block element which forms one or more stable ions with incomplete d orbitals. Scandium (Sc³⁺ is 3d⁰) and zinc (Zn²⁺ is 3d¹⁰) are d-block but not transition elements.' },
    { t: 'Characteristic properties', d: 'Variable oxidation states, coloured ions and compounds, catalytic activity, formation of complex ions. Also hard, dense, high melting points, similar atomic radii across the series.' },
    { t: 'Ligand', d: 'A species that contains a lone pair of electrons that forms a dative covalent bond to a central metal atom or ion. Monodentate: H₂O, NH₃, Cl⁻, OH⁻, CN⁻. Bidentate: 1,2-diaminoethane (en) H₂NCH₂CH₂NH₂, ethanedioate C₂O₄²⁻. Polydentate: EDTA⁴⁻.' },
    { t: 'Complex ion and co-ordination number', d: 'Complex: a molecule or ion formed by a central metal atom or ion surrounded by one or more ligands. Co-ordination number = number of dative bonds to the metal. 6: octahedral, 90° ([Cu(H₂O)₆]²⁺, [Fe(CN)₆]³⁻). 4: tetrahedral with large ligands, 109.5° ([CuCl₄]²⁻, [CoCl₄]²⁻), or square planar ([Pt(NH₃)₂Cl₂], cisplatin). 2: linear ([Ag(NH₃)₂]⁺, Tollens\' reagent).' },
    { t: 'Why complexes are coloured', d: 'The ligands split the five d orbitals into two levels with a small energy gap ΔE. An electron absorbs a photon of visible light with E = hν equal to ΔE and is promoted; the light that is not absorbed is transmitted, so the colour seen is complementary to the colour absorbed. Changing the ligand, the oxidation state or the co-ordination number changes ΔE and so the colour. d⁰ (Sc³⁺, Ti⁴⁺) and d¹⁰ (Zn²⁺, Cu⁺) ions are colourless.' },
    { t: 'Common colours', d: '[Cu(H₂O)₆]²⁺ blue; [Cu(NH₃)₄(H₂O)₂]²⁺ deep blue; [CuCl₄]²⁻ yellow (green in mixtures). [Fe(H₂O)₆]²⁺ pale green; [Fe(H₂O)₆]³⁺ yellow-brown. [Cr(H₂O)₆]³⁺ green (violet when pure); Cr₂O₇²⁻ orange; CrO₄²⁻ yellow. [Co(H₂O)₆]²⁺ pink; [CoCl₄]²⁻ blue. MnO₄⁻ purple; Mn²⁺ very pale pink. Vanadium: VO₂⁺ (+5) yellow, VO²⁺ (+4) blue, V³⁺ green, V²⁺ violet.' },
    { t: 'Ligand substitution', f: '[Cu(H₂O)₆]²⁺ + 4NH₃ ⇌ [Cu(NH₃)₄(H₂O)₂]²⁺ + 4H₂O;   [Cu(H₂O)₆]²⁺ + 4Cl⁻ ⇌ [CuCl₄]²⁻ + 6H₂O', d: 'Ligands exchange when the new complex is more stable or the new ligand is in excess. Ammonia first precipitates Cu(OH)₂, then excess dissolves it to the deep blue complex. Concentrated HCl turns blue copper sulfate yellow-green; dilution reverses it.' },
    { t: 'Stability constant and the chelate effect', f: 'Kstab = [complex] / ([aqua ion][ligand]ⁿ)', d: 'The equilibrium constant for the formation of the complex ion in a solvent from its constituent ions or molecules; [H₂O] is left out. Larger means more stable. Multidentate ligands give much more stable complexes because replacing several monodentate ligands with one multidentate ligand increases the number of particles, so ΔS is positive and ΔG more negative.' },
    { t: 'Redox titrations', f: 'MnO₄⁻ + 8H⁺ + 5Fe²⁺ → Mn²⁺ + 4H₂O + 5Fe³⁺;   Cr₂O₇²⁻ + 14H⁺ + 6Fe²⁺ → 2Cr³⁺ + 7H₂O + 6Fe³⁺;   2S₂O₃²⁻ + I₂ → S₄O₆²⁻ + 2I⁻', d: 'Manganate(VII) is self-indicating: the end point is the first permanent pale pink. Acidify with dilute H₂SO₄, never HCl (chloride is oxidised). Iodine–thiosulfate: add starch near the end, blue-black to colourless.' },
    { t: 'Catalysis by transition metals', d: 'Variable oxidation states let them accept and donate electrons: Fe²⁺/Fe³⁺ catalyses S₂O₈²⁻ + 2I⁻ → 2SO₄²⁻ + I₂ (homogeneous, two steps, avoids the repulsion between two negative ions). Surfaces adsorb reactant molecules (heterogeneous: Fe in Haber, V₂O₅ in Contact, Ni in hydrogenation, Pt/Pd/Rh in catalytic converters).' },
    { t: 'Isomerism in complexes', d: 'Geometric (cis–trans) in square planar [Pt(NH₃)₂Cl₂] and octahedral [Co(NH₃)₄Cl₂]⁺. Optical isomers in octahedral complexes with three bidentate ligands, such as [Ni(en)₃]²⁺. Cisplatin is an anticancer drug that binds to DNA.' },
    { t: 'Colorimetry', d: 'Measures the concentration of a coloured solution. Use a filter of the colour the solution absorbs most (the complementary colour), measure the absorbance of standard solutions of known concentration and plot a calibration curve (absorbance is proportional to concentration), then read the unknown concentration off the curve. For a pale ion, first add a ligand that forms an intensely coloured complex, such as thiocyanate with Fe³⁺ (blood red).' },
    { t: 'Haemoglobin and carbon monoxide', d: 'Each of the four chains of haemoglobin holds a haem group: an Fe²⁺ ion at the centre of a porphyrin ring, a tetradentate ligand bonded through four nitrogen atoms. The fifth position bonds to the protein; the sixth bonds O₂ reversibly, so oxygen is picked up in the lungs and released in the tissues. CO is a better ligand: it bonds to Fe²⁺ about 200 times more strongly and does not easily come off, so the haemoglobin can no longer carry oxygen. Treatment is breathing pure oxygen to displace the CO.' }
  ]},

  { id: 'aqueous', title: 'Aqueous inorganic chemistry', area: 'inorganic', topic: 'aqueous-inorganic', items: [
    { t: 'Acid–base theories', d: 'Arrhenius: an acid releases H⁺ ions in water and a base releases OH⁻ ions; limited to aqueous solutions, so it cannot explain ammonia as a base or NH₃ + HCl in the gas phase. Brønsted–Lowry: an acid is a proton donor, a base a proton acceptor; works in any solvent. Lewis: an acid is an electron-pair acceptor, a base an electron-pair donor; the widest definition, covering reactions with no protons at all. Every Brønsted–Lowry base is also a Lewis base.' },
    { t: 'Lewis acids and bases', f: 'BF₃ + NH₃ → F₃B←NH₃;   in [Cu(H₂O)₆]²⁺ the Cu²⁺ ion is the Lewis acid and each H₂O a Lewis base', d: 'A Lewis base has a lone pair it donates to form a dative bond: NH₃, H₂O, OH⁻, Cl⁻, every ligand. A Lewis acid has an empty orbital that accepts the pair: H⁺, BF₃, AlCl₃ (the halogen carrier in Friedel–Crafts reactions), and metal ions forming complexes.' },
    { t: 'Acidity of metal-aqua ions', f: '[Fe(H₂O)₆]³⁺ + H₂O ⇌ [Fe(H₂O)₅(OH)]²⁺ + H₃O⁺', d: 'The metal ion polarises the O–H bonds of the water ligands; the higher the charge density, the more acidic. 3+ aqua ions (Al³⁺, Fe³⁺, Cr³⁺) are noticeably acidic, pH about 2–3; 2+ ions are only slightly acidic, pH about 6.' },
    { t: 'With sodium hydroxide, from the data booklet', d: 'Al³⁺: white precipitate, soluble in excess. NH₄⁺: no precipitate, ammonia on heating. Ba²⁺: no precipitate. Ca²⁺: white precipitate only at high concentration. Cr³⁺: grey-green precipitate, soluble in excess giving a dark green solution. Cu²⁺: pale blue precipitate, insoluble in excess. Fe²⁺: green precipitate turning brown in air, insoluble in excess. Fe³⁺: red-brown precipitate, insoluble in excess. Pb²⁺: white precipitate, soluble in excess. Mg²⁺: white precipitate, insoluble in excess. Mn²⁺: off-white precipitate rapidly turning brown in air, insoluble in excess. Zn²⁺: white precipitate, soluble in excess.' },
    { t: 'With aqueous ammonia, from the data booklet', d: 'Al³⁺: white precipitate, insoluble in excess. Ba²⁺, Ca²⁺: no precipitate. Cr³⁺: grey-green precipitate, insoluble in excess. Cu²⁺: blue precipitate, soluble in excess giving a dark blue solution. Fe²⁺: green precipitate turning brown in air, insoluble in excess. Fe³⁺: red-brown precipitate, insoluble in excess. Pb²⁺: white precipitate, insoluble in excess. Mg²⁺: white precipitate, insoluble in excess. Mn²⁺: off-white precipitate turning brown in air, insoluble in excess. Zn²⁺: white precipitate, soluble in excess. Lead(II) is distinguished from aluminium by the insolubility of lead(II) chloride.' },
    { t: 'Telling the tests apart', d: 'Soluble in excess NaOH but not excess NH₃: Al³⁺, Pb²⁺, Cr³⁺ (amphoteric hydroxides, deprotonation). Soluble in both: Zn²⁺ (amphoteric and forms an ammine complex). Insoluble in NaOH but soluble in NH₃: Cu²⁺ (ligand exchange to [Cu(NH₃)₄(H₂O)₂]²⁺).' },
    { t: 'Amphoteric hydroxides', f: 'Al(OH)₃ + OH⁻ → [Al(OH)₄]⁻;   Cr(OH)₃ + 3OH⁻ → [Cr(OH)₆]³⁻;   Zn(OH)₂ + 2OH⁻ → [Zn(OH)₄]²⁻;   Pb(OH)₂ + 2OH⁻ → [Pb(OH)₄]²⁻', d: 'They also dissolve in acid: Al(OH)₃ + 3H⁺ → Al³⁺ + 3H₂O.' },
    { t: 'With carbonate', d: '2+ ions give a metal carbonate precipitate (CuCO₃ blue-green, FeCO₃ green, no gas). 3+ ions (Al³⁺, Fe³⁺, Cr³⁺) are acidic enough to give effervescence of CO₂ and the metal hydroxide precipitate instead: 2Al³⁺ + 3CO₃²⁻ + 3H₂O → 2Al(OH)₃ + 3CO₂.' },
    { t: 'Anion tests, from the data booklet', d: 'CO₃²⁻: CO₂ liberated by dilute acids. CrO₄²⁻: yellow solution turns orange with acid; yellow precipitate with Ba²⁺; bright yellow precipitate with Pb²⁺. Cl⁻: white precipitate with Ag⁺ (soluble in NH₃) and with Pb²⁺. Br⁻: cream precipitate with Ag⁺ (partially soluble in NH₃); white with Pb²⁺. I⁻: yellow precipitate with Ag⁺ (insoluble in NH₃) and with Pb²⁺. NO₃⁻: NH₃ liberated on heating with OH⁻ and aluminium foil. NO₂⁻: as nitrate, and NO liberated by dilute acids (colourless NO turns to pale brown NO₂ in air). SO₄²⁻: white precipitate with Ba²⁺ or Pb²⁺, insoluble in excess dilute strong acid. SO₃²⁻: SO₂ liberated by dilute acids; white precipitate with Ba²⁺ that dissolves in excess dilute strong acid.' },
    { t: 'Gas tests, from the data booklet', d: 'NH₃: turns damp red litmus blue. CO₂: white precipitate with limewater, which dissolves in excess CO₂. Cl₂: bleaches damp litmus. H₂: pops with a lighted splint. O₂: relights a glowing splint. SO₂: turns acidified potassium dichromate(VI) from orange to green.' }
  ]},

  { id: 'organic', title: 'Nomenclature and isomerism', area: 'organic', topic: 'organic-basics', items: [
    { t: 'Homologous series', d: 'A family of compounds with the same functional group and the same general formula, each member differing from the next by CH₂, with similar chemical properties and gradually changing physical properties.' },
    { t: 'Functional group', d: 'The atom or group of atoms in a molecule responsible for its characteristic reactions.' },
    { t: 'Types of formula', d: 'Empirical (simplest ratio), molecular (actual numbers), structural (CH₃CH₂OH, shows the arrangement without drawing every bond), displayed (every atom and bond drawn), skeletal (carbon chain as zig-zag lines, hydrogens on carbon omitted, heteroatoms shown).' },
    { t: 'Naming', d: 'Root from the longest carbon chain containing the functional group: meth, eth, prop, but, pent, hex. Suffix from the group: -ane, -ene, -ol, -al, -one, -oic acid, -amine, -nitrile, -yl ...-oate for esters. Number so the functional group gets the lowest locant; list prefixes (bromo, chloro, hydroxy, methyl, nitro) alphabetically with di, tri for repeats.' },
    { t: 'Naming aromatic compounds', d: 'Most substituents are prefixes on benzene: chlorobenzene, nitrobenzene, methylbenzene. Some groups keep their own names: phenol C₆H₅OH, phenylamine C₆H₅NH₂, benzoic acid C₆H₅COOH, benzaldehyde C₆H₅CHO. When the ring is the substituent it is phenyl, C₆H₅–: phenylethene, phenylethanone C₆H₅COCH₃. Number the ring from the principal group to give the lowest locants: 2-nitrophenol, 1,4-dimethylbenzene, 2,4,6-tribromophenol. Esters: methyl benzoate, phenyl ethanoate.' },
    { t: 'Cyclic and heterocyclic compounds', d: 'Rings of carbon take the prefix cyclo-: cyclohexane (C₆H₁₂, general formula CₙH₂ₙ), cyclohexene, cyclohexanol. Heterocyclic compounds have at least one atom other than carbon in the ring, usually N, O or S: pyridine C₅H₅N, furan, pyrrole. Heterocycles are common in nature and medicine: the DNA bases, nicotine and many drugs.' },
    { t: 'Structural isomers', d: 'Same molecular formula, different structural formula. Chain (branching), positional (functional group moved along the chain), functional group (propanal and propanone; ethanol and methoxymethane).' },
    { t: 'Stereoisomers', d: 'Same structural formula, different arrangement of atoms in space. Two kinds: geometric and optical.' },
    { t: 'Geometric (E/Z, cis–trans) isomerism', d: 'Arises from restricted rotation about a C=C double bond when each carbon of the double bond carries two different groups. Z (cis): higher-priority groups on the same side; E (trans): opposite sides. Priority by atomic number of the atom attached.' },
    { t: 'Optical isomerism', d: 'A chiral carbon carries four different groups, so the molecule and its mirror image cannot be superimposed. The two enantiomers rotate the plane of plane-polarised light equally in opposite directions; a 50:50 racemic mixture is optically inactive. Enantiomers have identical chemical properties except with other chiral molecules (enzymes, drugs).' },
    { t: 'Chirality in drugs and living systems', d: 'Enzymes and receptors are built from chiral L-amino acids, so they interact differently with the two enantiomers of a drug, and often only one fits. Thalidomide: one enantiomer treated morning sickness, the other caused birth defects, and the two interconvert in the body. The two enantiomers of carvone smell of spearmint and of caraway. A laboratory synthesis from non-chiral reagents gives a racemic mixture that must be separated; making a single enantiomer (chiral catalysts, enzymes or chiral starting materials) allows a smaller dose with fewer side effects.' },
    { t: 'Nucleophile', d: 'An electron-pair donor that attacks an electron-deficient (δ+) carbon: OH⁻, CN⁻, NH₃, H₂O, halide ions.' },
    { t: 'Electrophile', d: 'An electron-pair acceptor that attacks electron-rich sites such as C=C or the benzene ring: NO₂⁺, H⁺, the δ+ bromine in Br₂, carbocations.' },
    { t: 'Free radical', d: 'A species with one or more unpaired electrons, formed by homolytic fission (Cl•, •CH₃). Very reactive; involved in chain reactions.' },
    { t: 'Bond fission', d: 'Homolytic: the bond breaks evenly, one electron to each atom, forming radicals (UV light, non-polar bonds). Heterolytic: both electrons go to one atom, forming ions (polar bonds).' },
    { t: 'Reaction types', d: 'Addition (two molecules become one), substitution (one atom or group swapped for another), elimination (a small molecule removed to create a double bond), hydrolysis (split by water), oxidation ([O]), reduction ([H]), condensation (two molecules join with loss of a small molecule), polymerisation.' },
    { t: 'Carbocation stability', d: 'Tertiary > secondary > primary. Alkyl groups have a positive inductive effect: they release electron density toward the positive carbon and spread the charge. Explains Markovnikov products and why tertiary halogenoalkanes react by Sₙ1.' }
  ]},

  { id: 'hydrocarbons', title: 'Alkanes and alkenes', area: 'organic', topic: 'hydrocarbons', items: [
    { t: 'Alkanes', f: 'CₙH₂ₙ₊₂', d: 'Saturated, non-polar, only London forces between molecules, so boiling point rises with chain length and falls with branching. Unreactive toward acids, bases and oxidising agents; they burn and they react with halogens in UV light.' },
    { t: 'Combustion', f: 'C₃H₈ + 5O₂ → 3CO₂ + 4H₂O', d: 'Incomplete combustion in a limited oxygen supply gives CO (toxic, binds haemoglobin) and carbon (soot).' },
    { t: 'Burning fuels and the environment', d: 'Complete combustion releases CO₂, a greenhouse gas. Incomplete combustion adds toxic CO and soot. Sulfur impurities burn to SO₂ (acid rain), so fuels are desulfurised. The high temperature in engines forms NO and NO₂ (acid rain, photochemical smog), and unburnt hydrocarbons add to smog. Catalytic converters (Pt, Pd, Rh) remove CO, NOₓ and unburnt hydrocarbons: 2CO + 2NO → 2CO₂ + N₂.' },
    { t: 'Fractional distillation of crude oil', d: 'Crude oil is heated until most of it vaporises, and the vapour rises up a column that is hot at the bottom and cooler at the top. Each fraction condenses at the level where the temperature falls below its boiling point, so a fraction is a mixture of alkanes with similar chain lengths. From the top: refinery gases (C₁–C₄, bottled gas), petrol (about C₅–C₁₀), naphtha (feedstock for chemicals), kerosene (about C₁₀–C₁₆, jet fuel), diesel or gas oil (about C₁₄–C₂₀), fuel oil (ships, power stations) and bitumen (roads, roofing). Longer chains: higher boiling point, more viscous, harder to ignite.' },
    { t: 'Cracking', f: 'C₁₀H₂₂ → C₈H₁₈ + C₂H₄', d: 'Long alkanes from fractional distillation are broken into shorter, more useful alkanes and alkenes with a zeolite or Al₂O₃ catalyst and heat. Products must balance in carbon and hydrogen.' },
    { t: 'Thermal and catalytic cracking', d: 'Thermal cracking: 400–900 °C and high pressure (about 70 atm). C–C bonds break by homolytic fission, so it goes through free radicals and gives a high proportion of alkenes such as ethene. Catalytic cracking: zeolite catalyst, about 450 °C, slight pressure. It goes through carbocation intermediates and gives branched alkanes, cycloalkanes and aromatic hydrocarbons for petrol. Both turn surplus long-chain fractions into more valuable shorter molecules.' },
    { t: 'Free-radical substitution', f: 'Initiation: Cl₂ → 2Cl• (UV).   Propagation: Cl• + CH₄ → HCl + •CH₃;   •CH₃ + Cl₂ → CH₃Cl + Cl•.   Termination: Cl• + Cl• → Cl₂;   •CH₃ + Cl• → CH₃Cl;   •CH₃ + •CH₃ → C₂H₆', d: 'Chain reaction; the radical is regenerated in propagation. Gives a mixture of products (further substitution to CH₂Cl₂, CHCl₃, CCl₄, plus ethane) so it is a poor synthesis. Ultraviolet light supplies the energy for homolytic fission.' },
    { t: 'Alkenes', f: 'CₙH₂ₙ', d: 'Unsaturated; the C=C bond is one σ and one π bond. The exposed π electron density attracts electrophiles. Planar around the double bond, 120°, restricted rotation.' },
    { t: 'Test for C=C', d: 'Shake with bromine water: orange to colourless (decolourised). Alkanes leave it orange. Cold dilute acidified KMnO₄ also goes from purple to colourless.' },
    { t: 'Electrophilic addition mechanism', d: 'Ethene + HBr: the π electrons attack the δ+ hydrogen; a C–H bond forms as the H–Br bond breaks heterolytically, giving a carbocation and Br⁻; the bromide lone pair forms a bond to the carbocation. With Br₂ the approach of the π electrons induces a dipole in the Br–Br bond. Draw curly arrows from the π bond to H, from the H–Br bond to Br, and from Br⁻ to C⁺.' },
    { t: 'Markovnikov\'s rule', d: 'When HX adds to an unsymmetrical alkene the hydrogen goes to the carbon that already has more hydrogens, because the reaction passes through the more stable, more substituted carbocation. Propene + HBr gives mainly 2-bromopropane.' },
    { t: 'Addition reactions', d: 'H₂, nickel catalyst, 150 °C: alkane (hardening oils to margarine). Br₂ at room temperature: 1,2-dibromoalkane. HBr at room temperature: bromoalkane. Steam, H₃PO₄ catalyst, 300 °C, 60 atm: alcohol. Cold dilute acidified KMnO₄: diol (purple to colourless).' },
    { t: 'Oxidative cleavage', d: 'Hot concentrated acidified KMnO₄ breaks the C=C completely. Each =CH₂ end becomes CO₂, each =CHR becomes a carboxylic acid RCOOH, each =CR₂ becomes a ketone. The products locate the double bond in an unknown alkene.' },
    { t: 'Addition polymerisation', d: 'Many alkene monomers join to give one long saturated chain; nothing else is formed. Draw the repeat unit by opening the C=C to C–C and continuing the bonds through the brackets: poly(ethene), poly(propene), poly(chloroethene) PVC, poly(tetrafluoroethene) PTFE, poly(phenylethene) polystyrene.' },
    { t: 'Disposal of polyalkenes', d: 'Chemically inert and non-biodegradable, so they persist in landfill. Burning releases CO₂ and, for PVC, HCl which must be scrubbed. Recycling by melting, or feedstock recycling by cracking back to monomers.' }
  ]},

  { id: 'halogeno', title: 'Halogenoalkanes', area: 'organic', topic: 'halogenoalkanes', items: [
    { t: 'The C–X bond', d: 'Polar (C δ+, X δ−) so the carbon is attacked by nucleophiles. Reactivity: iodoalkane > bromoalkane > chloroalkane, because the C–X bond enthalpy falls down the group; bond strength, not polarity, controls the rate.' },
    { t: 'Classification', d: 'Primary: the carbon bearing X is attached to one other carbon; secondary: two; tertiary: three.' },
    { t: 'Nucleophilic substitution with hydroxide', f: 'CH₃CH₂Br + OH⁻ → CH₃CH₂OH + Br⁻', d: 'Aqueous NaOH, heat under reflux. Hydrolysis to an alcohol. Water alone works slowly.' },
    { t: 'With cyanide', f: 'CH₃CH₂Br + CN⁻ → CH₃CH₂CN + Br⁻', d: 'KCN in ethanol, heat under reflux. Gives a nitrile and lengthens the carbon chain by one; the nitrile can then be hydrolysed to a carboxylic acid or reduced to an amine.' },
    { t: 'With ammonia', f: 'CH₃CH₂Br + 2NH₃ → CH₃CH₂NH₂ + NH₄Br', d: 'Excess concentrated ammonia in ethanol, heated in a sealed tube. Excess ammonia limits further substitution to secondary and tertiary amines.' },
    { t: 'Sₙ2 mechanism', d: 'Primary halogenoalkanes. One step: the nucleophile attacks the δ+ carbon from the side opposite the halogen while the C–X bond breaks, through a five-coordinate transition state. Rate = k[RX][Nu⁻], second order. Inverts the configuration at a chiral centre.' },
    { t: 'Sₙ1 mechanism', d: 'Tertiary halogenoalkanes. Two steps: the C–X bond breaks first to give a planar carbocation (slow, rate-determining), then the nucleophile attacks from either face. Rate = k[RX], first order. A chiral centre gives a racemic mixture.' },
    { t: 'Elimination', f: 'CH₃CH₂Br + KOH → CH₂=CH₂ + KBr + H₂O', d: 'KOH in ethanol, heat. The hydroxide acts as a base, removing a hydrogen from the carbon next to the C–X carbon. Ethanolic conditions and higher temperatures favour elimination; aqueous conditions favour substitution; tertiary halogenoalkanes favour elimination.' },
    { t: 'Rate of hydrolysis test', d: 'Warm the halogenoalkane with aqueous silver nitrate in ethanol. The halide released precipitates: yellow AgI appears fastest, cream AgBr next, white AgCl slowest, matching the C–X bond enthalpies.' },
    { t: 'CFCs and the ozone layer', f: 'CCl₂F₂ → •CClF₂ + Cl• (UV);   Cl• + O₃ → ClO• + O₂;   ClO• + O → Cl• + O₂', d: 'CFCs are inert enough to reach the stratosphere, where UV breaks the weaker C–Cl bond homolytically. One chlorine radical destroys many ozone molecules because it is regenerated (a catalyst). Replaced by HFCs, which contain no chlorine.' }
  ]},

  { id: 'alcohols', title: 'Alcohols and phenols', area: 'organic', topic: 'alcohols', items: [
    { t: 'Classification', d: 'Primary: the carbon bearing OH is bonded to one other carbon (or none, methanol); secondary: two; tertiary: three. Hydrogen bonding gives high boiling points and water solubility for short chains.' },
    { t: 'Preparation', f: 'C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂ (fermentation)', d: 'Hydration of an alkene with steam and H₃PO₄; hydrolysis of a halogenoalkane with aqueous NaOH; reduction of an aldehyde or ketone with NaBH₄; fermentation of glucose with yeast at about 37 °C without oxygen.' },
    { t: 'Ethanol: hydration versus fermentation', f: 'C₂H₄ + H₂O ⇌ C₂H₅OH;   C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂', d: 'Hydration of ethene: steam, H₃PO₄ catalyst, 300 °C, 60–70 atm. A fast continuous process giving pure ethanol with 100 % atom economy, but the ethene comes from crude oil, a finite resource, and it needs a lot of energy. Fermentation: yeast, about 35 °C, no air. Uses renewable sugar from plants at a low temperature, but it is a slow batch process, stops at about 15 % ethanol when the yeast die, needs fractional distillation, and has an atom economy of only about 51 %.' },
    { t: 'Biofuels and carbon neutrality', f: '6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (photosynthesis)', d: 'Bioethanol is called carbon neutral: the six CO₂ the plant absorbs to make one glucose equal the two CO₂ released in fermentation plus the four released when the two ethanol molecules burn. In practice it is not fully neutral, because fossil fuels are burned for farming, fertilisers, transport and distillation. Biofuels are renewable, but the crops compete with food for land and water and can drive deforestation.' },
    { t: 'Oxidation', d: 'Acidified potassium dichromate(VI), orange to green. Primary alcohol, heat and distil the product as it forms: aldehyde. Primary alcohol, heat under reflux with excess oxidant: carboxylic acid. Secondary alcohol: ketone. Tertiary alcohol: not oxidised, stays orange. Write [O] in equations: CH₃CH₂OH + [O] → CH₃CHO + H₂O.' },
    { t: 'Dehydration', f: 'CH₃CH₂OH → CH₂=CH₂ + H₂O', d: 'Concentrated sulfuric or phosphoric acid at 170 °C, or the vapour passed over heated aluminium oxide. An elimination; unsymmetrical alcohols give a mixture of alkenes, including E and Z isomers (butan-2-ol gives but-1-ene, E-but-2-ene and Z-but-2-ene).' },
    { t: 'Esterification', f: 'CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O', d: 'Concentrated sulfuric acid catalyst, heat under reflux. Reversible and slow; an acyl chloride instead of the acid reacts fast and completely at room temperature, giving HCl fumes.' },
    { t: 'Reactions that test for the OH group', f: '2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂;   C₂H₅OH + PCl₅ → C₂H₅Cl + POCl₃ + HCl', d: 'Sodium gives effervescence of hydrogen. PCl₅ gives steamy fumes of HCl that turn damp blue litmus red. Both are positive for carboxylic acids too.' },
    { t: 'Halogenation', f: 'C₂H₅OH + HBr → C₂H₅Br + H₂O', d: 'Reflux with KBr and concentrated H₂SO₄ (makes HBr in situ), or with PCl₅ or SOCl₂ for chloroalkanes.' },
    { t: 'Tri-iodomethane (iodoform) test', d: 'Warm with iodine and sodium hydroxide. A yellow precipitate of CHI₃ with an antiseptic smell shows the CH₃CH(OH)– group: ethanol, propan-2-ol, butan-2-ol. Methanol and propan-1-ol are negative. The same test detects CH₃CO– carbonyls.' },
    { t: 'Phenol as an acid', f: 'C₆H₅OH + NaOH → C₆H₅O⁻Na⁺ + H₂O', d: 'A weak acid (pKa about 10), stronger than alcohols because the negative charge of the phenoxide ion is delocalised into the ring. Reacts with NaOH and sodium, but not with sodium carbonate; carboxylic acids react with carbonate. This distinguishes phenol from a carboxylic acid.' },
    { t: 'Phenol: ring substitution', d: 'The OH lone pair is delocalised into the ring, activating it, so phenol substitutes much more readily than benzene at the 2, 4 and 6 positions. Bromine water, no catalyst, room temperature: white precipitate of 2,4,6-tribromophenol and the bromine is decolourised. Dilute nitric acid, no H₂SO₄: 2-nitrophenol and 4-nitrophenol.' },
    { t: 'Test for phenol', d: 'Neutral iron(III) chloride solution gives a violet (purple) colour.' }
  ]},

  { id: 'carbonyl', title: 'Carbonyls, acids and esters', area: 'organic', topic: 'carbonyl', items: [
    { t: 'Aldehydes and ketones', d: 'Aldehydes RCHO have the C=O at the end of the chain; ketones RCOR\' have it between two carbons. The C=O is polar, so nucleophiles attack the δ+ carbon. Small ones dissolve in water by hydrogen bonding to water molecules, but they cannot hydrogen bond to each other, so boiling points are below those of alcohols.' },
    { t: 'Preparation', d: 'Oxidise a primary alcohol with acidified K₂Cr₂O₇ and distil (aldehyde); oxidise a secondary alcohol (ketone).' },
    { t: 'Nucleophilic addition of HCN', f: 'CH₃CHO + HCN → CH₃CH(OH)CN', d: 'KCN with a little dilute acid (HCN itself is a gas and toxic). CN⁻ attacks the δ+ carbon, the π bond breaks to give O⁻, which takes H⁺ from HCN or water. Product is a 2-hydroxynitrile with a new chiral centre, formed as a racemic mixture because the planar carbonyl is attacked equally from both faces.' },
    { t: 'Reduction', f: 'CH₃CHO + 2[H] → CH₃CH₂OH;   CH₃COCH₃ + 2[H] → CH₃CH(OH)CH₃', d: 'NaBH₄ in water or ethanol (or LiAlH₄, or H₂ with nickel). Aldehyde to primary alcohol, ketone to secondary. NaBH₄ does not reduce C=C or carboxylic acids.' },
    { t: '2,4-DNPH', d: '2,4-dinitrophenylhydrazine gives an orange-yellow precipitate with any aldehyde or ketone (a condensation), but not with acids or esters. The melting point of the purified derivative identifies the original carbonyl compound.' },
    { t: 'Tollens\' reagent', d: 'Ammoniacal silver nitrate, [Ag(NH₃)₂]⁺, warmed. Aldehydes are oxidised to carboxylate ions and Ag⁺ is reduced to a silver mirror. Ketones do not react. Distinguishes aldehydes from ketones.' },
    { t: 'Fehling\'s and Benedict\'s solutions', d: 'Blue Cu²⁺ complex, warmed. Aldehydes reduce it to a brick-red precipitate of Cu₂O; ketones give no change.' },
    { t: 'Iodoform test on carbonyls', d: 'CH₃CO– compounds (ethanal and methyl ketones) give a yellow precipitate of CHI₃ with I₂ and NaOH. Propanal is negative, propanone positive.' },
    { t: 'Carboxylic acids', f: 'CH₃COOH ⇌ CH₃COO⁻ + H⁺;   2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂', d: 'Weak acids. React with metals (H₂), bases (salt + water) and carbonates (effervescence of CO₂, which phenol does not give). Made by oxidising a primary alcohol or aldehyde under reflux, or by hydrolysing a nitrile or an ester. Dimerise through hydrogen bonds.' },
    { t: 'Acid strength and structure', d: 'Electron-withdrawing groups near the COOH stabilise the carboxylate anion and increase Ka: CCl₃COOH > CHCl₂COOH > CH₂ClCOOH > CH₃COOH. Alkyl groups are electron-releasing (positive inductive effect), destabilise the anion and so weaken the acid: methanoic > ethanoic > propanoic.' },
    { t: 'Acyl chlorides', f: 'CH₃COCl + H₂O → CH₃COOH + HCl;   CH₃COCl + C₂H₅OH → CH₃COOC₂H₅ + HCl;   CH₃COCl + 2NH₃ → CH₃CONH₂ + NH₄Cl', d: 'Made from the acid with PCl₅ or SOCl₂. Very reactive because chlorine and oxygen both withdraw electrons from the carbonyl carbon. React by nucleophilic addition–elimination with water, alcohols, ammonia and amines, giving fumes of HCl.' },
    { t: 'Acid anhydrides', f: '(CH₃CO)₂O + H₂O → 2CH₃COOH;   (CH₃CO)₂O + C₂H₅OH → CH₃COOC₂H₅ + CH₃COOH;   (CH₃CO)₂O + 2NH₃ → CH₃CONH₂ + CH₃COONH₄', d: 'Two acyl groups joined through an oxygen atom, as in ethanoic anhydride. They react like acyl chlorides, by nucleophilic addition–elimination with water, alcohols, ammonia and amines, but more slowly, and the by-product is a carboxylic acid instead of HCl.' },
    { t: 'Aspirin', f: 'HOC₆H₄COOH + (CH₃CO)₂O → CH₃COOC₆H₄COOH + CH₃COOH', d: 'Made by acylating the phenol OH group of 2-hydroxybenzoic acid (salicylic acid) with ethanoic anhydride. Industry uses the anhydride rather than ethanoyl chloride because it is cheaper, less corrosive, reacts less violently, is hydrolysed less easily, and gives ethanoic acid instead of toxic HCl fumes. Purify by recrystallisation; pure aspirin melts sharply at about 136 °C and gives no violet colour with iron(III) chloride, showing no unreacted phenol group is left.' },
    { t: 'Esters', d: 'Named alcohol part first: ethanol + ethanoic acid gives ethyl ethanoate CH₃COOCH₂CH₃. Sweet smelling; used as solvents, flavourings and plasticisers. Made from acid + alcohol with concentrated H₂SO₄ (reversible) or from an acyl chloride (fast).' },
    { t: 'Hydrolysis of esters', f: 'CH₃COOC₂H₅ + H₂O ⇌ CH₃COOH + C₂H₅OH (acid);   CH₃COOC₂H₅ + NaOH → CH₃COONa + C₂H₅OH (alkali)', d: 'Acid hydrolysis (dilute H₂SO₄, reflux) is reversible and incomplete. Alkaline hydrolysis (NaOH, reflux) goes to completion because the carboxylate salt is removed from the equilibrium; add acid afterwards to obtain the acid. Saponification of fats gives soap.' },
    { t: 'Fats, soaps and biodiesel', d: 'Fats and oils are triesters of propane-1,2,3-triol (glycerol) with long-chain fatty acids. Boiling with NaOH (saponification) gives glycerol and the sodium salts of the fatty acids, which are soap: the anion has an ionic head that dissolves in water and a long hydrocarbon tail that dissolves in grease. Biodiesel: vegetable oil warmed with methanol and a KOH or NaOH catalyst (transesterification) gives methyl esters of the fatty acids plus glycerol; renewable and biodegradable.' },
    { t: 'Reduction of acids', d: 'LiAlH₄ in dry ether reduces carboxylic acids to primary alcohols; NaBH₄ is not strong enough.' }
  ]},

  { id: 'arenes', title: 'Arenes', area: 'organic', topic: 'aromatic', items: [
    { t: 'Structure of benzene', d: 'A planar regular hexagon, each carbon sp² with bond angles of 120°. The six p orbitals overlap sideways above and below the ring to form a delocalised π system. All C–C bonds are equal, 0.139 nm, between a single (0.154) and a double (0.134). Evidence: bond lengths, only one 1,2-disubstituted isomer, no reaction with bromine water, and the enthalpy of hydrogenation −208 kJ mol⁻¹ against −360 expected for three separate C=C (delocalisation stabilises by about 152 kJ mol⁻¹).' },
    { t: 'Electrophilic substitution', d: 'Substitution keeps the stable delocalised ring; addition would destroy it. Mechanism: the electrophile is attracted to the π electrons, a curly arrow from the ring to the electrophile forms a C–E bond and gives a positively charged intermediate with the charge spread over the remaining five carbons (drawn as a horseshoe); loss of H⁺ from that carbon (curly arrow from the C–H bond back into the ring) restores the delocalisation.' },
    { t: 'Nitration', f: 'HNO₃ + 2H₂SO₄ → NO₂⁺ + H₃O⁺ + 2HSO₄⁻;   C₆H₆ + NO₂⁺ → C₆H₅NO₂ + H⁺', d: 'Concentrated nitric and concentrated sulfuric acids at 50–55 °C; sulfuric acid is the catalyst that generates the nitronium ion. Above 55 °C dinitration occurs. Nitrobenzene is reduced to phenylamine for dyes.' },
    { t: 'Halogenation', f: 'Br₂ + FeBr₃ → Br⁺ + FeBr₄⁻;   C₆H₆ + Br₂ → C₆H₅Br + HBr', d: 'A halogen carrier (FeBr₃, AlCl₃ or iron filings) polarises the halogen to create the electrophile. Room temperature, no light. In sunlight and without a carrier, methylbenzene substitutes on the side chain by free radicals instead.' },
    { t: 'Friedel–Crafts reactions', f: 'CH₃Cl + AlCl₃ → CH₃⁺ + AlCl₄⁻;   C₆H₆ + CH₃COCl → C₆H₅COCH₃ + HCl', d: 'Alkylation with a halogenoalkane and AlCl₃ attaches an alkyl group; acylation with an acyl chloride and AlCl₃ attaches an acyl group giving a phenyl ketone. Anhydrous conditions, heat under reflux.' },
    { t: 'Side-chain oxidation', f: 'C₆H₅CH₃ + 3[O] → C₆H₅COOH + H₂O', d: 'Hot alkaline KMnO₄ followed by acid oxidises any alkyl side chain with a hydrogen on the benzylic carbon to benzoic acid, whatever its length.' },
    { t: 'Directing effects', d: 'Electron-donating groups activate the ring and direct to positions 2 and 4: OH, NH₂, OR, alkyl. Electron-withdrawing groups deactivate and direct to position 3: NO₂, COOH, CHO, COR, CN, SO₃H. Halogens deactivate but direct 2,4.' },
    { t: 'Phenol versus benzene', d: 'Phenol reacts with bromine water at once without a catalyst (white precipitate of 2,4,6-tribromophenol); benzene needs a halogen carrier and gives only monobromination. The OH lone pair delocalised into the ring raises its electron density.' },
    { t: 'Hydrogenation', f: 'C₆H₆ + 3H₂ → C₆H₁₂', d: 'Nickel catalyst, heat and pressure, gives cyclohexane.' }
  ]},

  { id: 'amines', title: 'Amines and amino acids', area: 'organic', topic: 'amines-amino', items: [
    { t: 'Amines', f: 'CH₃CH₂NH₂ + HCl → CH₃CH₂NH₃⁺Cl⁻', d: 'Derivatives of ammonia: primary RNH₂, secondary R₂NH, tertiary R₃N. Bases because the lone pair on nitrogen accepts a proton; nucleophiles for the same reason. Hydrogen bonding makes small amines water soluble with a fishy smell.' },
    { t: 'Base strength', d: 'Ethylamine > ammonia > phenylamine. Alkyl groups have a positive inductive effect, releasing electron density onto the nitrogen and making the lone pair more available for donation. In phenylamine the lone pair is delocalised into the benzene ring, so it is much less available. Amides are not basic at all: the lone pair is delocalised onto the C=O.' },
    { t: 'Preparation of amines', f: 'CH₃CH₂Br + 2NH₃ → CH₃CH₂NH₂ + NH₄Br;   CH₃CN + 4[H] → CH₃CH₂NH₂;   C₆H₅NO₂ + 6[H] → C₆H₅NH₂ + 2H₂O', d: 'Halogenoalkane with excess ethanolic ammonia in a sealed tube. Nitrile reduced with LiAlH₄ or H₂ over nickel. Nitrobenzene reduced with tin and concentrated hydrochloric acid under reflux, then NaOH to free the amine from its salt.' },
    { t: 'Amines with acyl chlorides', f: 'CH₃COCl + CH₃NH₂ → CH₃CONHCH₃ + HCl', d: 'Nucleophilic addition–elimination giving an N-substituted amide. Excess amine mops up the HCl.' },
    { t: 'Phenylamine', d: 'Weak base, sparingly soluble. Bromine water gives a white precipitate of 2,4,6-tribromophenylamine (ring activated by the NH₂ group). Diazotisation with nitrous acid (NaNO₂ and HCl) below 10 °C gives the benzenediazonium ion C₆H₅N₂⁺; coupling with phenol in alkali gives an azo dye (yellow-orange). Above 10 °C the diazonium salt decomposes to phenol and nitrogen.' },
    { t: 'Amides', f: 'CH₃CONH₂ + H₂O + HCl → CH₃COOH + NH₄Cl;   CH₃CONH₂ + NaOH → CH₃COONa + NH₃', d: 'Made from an acyl chloride and ammonia. Hydrolysed by heating with acid (acid and ammonium salt) or alkali (carboxylate and ammonia). Neutral, not basic.' },
    { t: 'Amino acids', d: 'H₂N–CHR–COOH: an amine and a carboxylic acid on the same carbon, so amphoteric. Twenty occur in proteins; all except glycine (R = H) have a chiral α-carbon.' },
    { t: 'Zwitterion and isoelectric point', d: 'In the solid and near neutral pH the amino acid exists as the zwitterion ⁺H₃N–CHR–COO⁻, which is why amino acids are crystalline, high melting and water soluble. At low pH the cation ⁺H₃N–CHR–COOH; at high pH the anion H₂N–CHR–COO⁻. The isoelectric point is the pH at which the zwitterion predominates, there is no net charge and no movement in electrophoresis.' },
    { t: 'Peptide bond', d: 'The amide link –CONH– formed by condensation between the COOH of one amino acid and the NH₂ of another with loss of water. Two amino acids give a dipeptide (two possible sequences), many give a polypeptide or protein. Hydrolysis: heat under reflux with 6 mol dm⁻³ HCl for 24 hours, then identify the amino acids by chromatography or electrophoresis.' },
    { t: 'Protein structure', d: 'Primary: the sequence of amino acids held by peptide bonds. Secondary: the α-helix or β-pleated sheet, held by hydrogen bonds between C=O and N–H groups of the backbone. Tertiary: the overall three-dimensional folding held by hydrogen bonds, ionic attractions between charged side chains, disulfide bridges (–S–S– between cysteine residues) and van der Waals\' forces between side chains. Quaternary: several polypeptide chains together (haemoglobin has four).' },
    { t: 'Denaturation', d: 'Heat, extremes of pH or heavy metal ions break the hydrogen bonds and ionic interactions holding the tertiary and secondary structure, so the protein loses its shape and function. Peptide bonds are not broken.' },
    { t: 'DNA', d: 'A nucleotide is a phosphate, a deoxyribose sugar and a base (A, T, C, G). Two antiparallel strands twist into a double helix held by hydrogen bonds between complementary bases: adenine–thymine two hydrogen bonds, cytosine–guanine three. Replication copies each strand. A codon of three bases on mRNA (where U replaces T) codes for one amino acid; tRNA carries the complementary anticodon and the amino acid to the ribosome.' }
  ]},

  { id: 'life', title: 'Chemistry of life', area: 'organic', topic: 'amines-amino', items: [
    { t: 'Enzyme action', d: 'An enzyme is a protein catalyst. The substrate fits the active site like a key in a lock, forming an enzyme–substrate complex, and reacts by a route with a lower activation energy; the shape of the site makes the enzyme specific. Rate against substrate concentration: first order at low concentration, levelling off to zero order once every active site is occupied.' },
    { t: 'Competitive and non-competitive inhibition', d: 'A competitive inhibitor has a shape similar to the substrate and occupies the active site; adding more substrate reduces its effect. A non-competitive inhibitor, such as a heavy metal ion, binds elsewhere and changes the shape of the active site; more substrate does not help. Many drugs and poisons are enzyme inhibitors.' },
    { t: 'Protein sequence from hydrolysis', d: 'Complete hydrolysis (6 mol dm⁻³ HCl, reflux, 24 hours) shows which amino acids are present, identified by chromatography or electrophoresis, but not their order. Partial hydrolysis gives short overlapping peptides; lining up the overlaps gives the sequence.' },
    { t: 'Structure and function', d: 'A change in the primary structure can change how the chain folds (hydrogen bonds, ionic attractions, disulfide bridges, interactions between non-polar side chains), so the tertiary structure and the shape of an active site or binding site change and the protein may stop working, or work differently.' },
    { t: 'DNA mutation and genetic disease', d: 'A mutation is a change in the base sequence of DNA. A substitution changes one codon and so at most one amino acid (sometimes none, because several codons code for the same amino acid). An insertion or deletion shifts the reading frame and changes every amino acid after it. Sickle-cell anaemia: one base substitution changes glutamic acid (polar side chain) to valine (non-polar) in haemoglobin, so the molecules stick together and red blood cells become sickle shaped. Cystic fibrosis: deleting three bases removes one amino acid from a membrane protein.' },
    { t: 'ATP and energy', f: 'ATP + H₂O → ADP + Pi   (about −30 kJ mol⁻¹)', d: 'Adenosine triphosphate: the base adenine, the sugar ribose and a chain of three phosphate groups (block diagram: adenine–ribose–P–P–P). Enzyme-catalysed hydrolysis of the end phosphate releases energy for muscle contraction, active transport and synthesis. Respiration of glucose supplies the energy to join ADP and phosphate back into ATP, so ATP is the energy currency of the cell.' },
    { t: 'Metals essential to life', d: 'Iron: Fe²⁺ in haemoglobin and myoglobin carries oxygen; Fe²⁺/Fe³⁺ in cytochromes transfers electrons. Zinc: at the active site of many enzymes, such as carbonic anhydrase. Sodium and potassium: nerve impulses and fluid balance. Calcium: bones and teeth (calcium phosphate), muscle contraction, blood clotting. Magnesium: at the centre of chlorophyll, and needed by enzymes that use ATP. Copper: electron-transfer enzymes. Cobalt: vitamin B₁₂.' },
    { t: 'Heavy metal pollution', d: 'Lead: old paint and pipes, leaded petrol, batteries, mining and smelting. Mercury: gold mining, burning coal, and chemical plants that used mercury (the Nura river in Kazakhstan was polluted by the acetaldehyde plant at Temirtau); in water it is converted to methylmercury, which builds up in fish (Minamata disease, Japan). Cadmium: Ni–Cd batteries, zinc smelting, phosphate fertilisers. Dissolved ions reach soil and water, are taken up by plants and plankton and are not excreted, so they accumulate in tissues and become more concentrated at each step up the food chain.' },
    { t: 'Heavy metals and proteins', d: 'Pb²⁺, Hg²⁺ and Cd²⁺ bond strongly to the sulfur of –SH groups in cysteine and to –COO⁻ groups. This breaks disulfide bridges and ionic attractions, changes the tertiary structure and inactivates enzymes. They can also displace essential ions such as Zn²⁺ from active sites; lead blocks enzymes that make haem, causing anaemia. Treatment: a chelating agent such as EDTA binds the metal ion so it can be excreted.' }
  ]},

  { id: 'polymers', title: 'Polymerisation', area: 'organic', topic: 'polymers', items: [
    { t: 'Addition polymerisation', d: 'Alkene monomers join through their C=C bonds to give a saturated chain with no other product; the polymer has the same empirical formula as the monomer. To find the monomer, take the two-carbon repeat unit and reinstate the double bond.' },
    { t: 'Making poly(ethene)', d: 'Low-density poly(ethene): very high pressure (about 2000 atm), about 200 °C, a trace of oxygen as initiator. A free-radical process gives branched chains that pack loosely: soft and flexible (bags, film). High-density poly(ethene): Ziegler–Natta catalyst, low pressure, about 60 °C. Gives unbranched chains that pack closely: stronger with a higher melting point (bottles, pipes).' },
    { t: 'Condensation polymerisation', d: 'Each monomer has two functional groups; they join in a chain by condensation, eliminating a small molecule (water, or HCl from an acyl chloride) at every link. The repeat unit contains the link; the polymer does not have the empirical formula of the monomers.' },
    { t: 'Polyesters', d: 'A diol with a dicarboxylic acid or dioyl chloride, ester links –COO–. Terylene (PET): ethane-1,2-diol and benzene-1,4-dicarboxylic acid (terephthalic acid). Poly(lactic acid) from a single hydroxycarboxylic acid monomer. Used for fibres and bottles; hydrolysed by acid or alkali.' },
    { t: 'Polyamides', d: 'A diamine with a dicarboxylic acid or dioyl chloride, amide links –CONH–. Nylon-6,6: hexane-1,6-diamine and hexanedioic acid (the numbers are the carbons in each monomer). Kevlar: benzene-1,4-diamine and benzene-1,4-dicarboxylic acid; its flat aromatic chains hydrogen bond into sheets, giving great strength. Proteins are natural polyamides. Nylon-6 from one monomer, 6-aminohexanoic acid or its lactam.' },
    { t: 'Drawing repeat units', d: 'Show the link (ester or amide) explicitly, continue the bonds through the brackets at both ends, and write n outside. For addition polymers show the backbone C–C with the substituents in place.' },
    { t: 'Hydrolysis and biodegradability', d: 'Polyesters and polyamides contain polar links that can be hydrolysed by acid or alkali (and by enzymes) back to their monomers, so they are potentially biodegradable. Polyalkenes have a non-polar all-carbon backbone and are not. Kevlar is hydrolysed to benzene-1,4-dicarboxylic acid and benzene-1,4-diamine.' },
    { t: 'Properties and structure', d: 'Hydrogen bonds between chains strengthen polyamides (nylon, Kevlar). Linear chains pack closely (HDPE, dense and strong); branched chains cannot (LDPE, soft). Cross-links between chains (vulcanised rubber, thermosets) prevent melting. Longer chains mean stronger London forces and higher softening temperatures.' }
  ]},

  { id: 'materials', title: 'Chemistry and materials design', area: 'organic', topic: 'materials', items: [
    { t: 'Compounds with physiological activity', d: 'Drugs, hormones, pesticides and poisons act by binding to enzymes or receptors. Many are found in nature: salicylic acid in willow bark (the basis of aspirin), morphine in the opium poppy, penicillin from a mould, quinine from cinchona bark. Synthesising them gives larger amounts of consistent purity, protects the natural source, and lets chemists modify the structure to improve activity or reduce side effects.' },
    { t: 'Designing a drug', d: 'Identify the target, an enzyme or receptor, and find its three-dimensional structure by X-ray crystallography, using NMR and mass spectrometry for the molecules involved. Computer modelling designs molecules whose shape and functional groups fit the site, bonding through hydrogen bonds, ionic attractions and van der Waals forces. A promising lead compound is modified step by step to improve activity and reduce side effects, then tested and taken through clinical trials. Chirality matters: often only one enantiomer fits.' },
    { t: 'Examples of synthetic drugs', d: 'Aspirin: relieves pain, fever and inflammation and thins the blood; can cause stomach bleeding. Paracetamol: pain and fever; an overdose damages the liver. Ibuprofen: anti-inflammatory. Penicillins and semi-synthetic derivatives such as amoxicillin: antibiotics. Cisplatin: anticancer. Antacids such as Mg(OH)₂, CaCO₃ and NaHCO₃ neutralise excess stomach acid.' },
    { t: 'Drug delivery', d: 'Problems: the drug may be destroyed by stomach acid or enzymes (insulin must be injected), may not dissolve or cross cell membranes, may reach healthy tissue and cause side effects, or may be excreted too quickly. Solutions: soluble salts (the sodium salt of an acid, the hydrochloride of an amine), coatings that dissolve only in the intestine, slow-release capsules, skin patches, inhalers and injections, and carriers such as liposomes or nanoparticles that take the drug to the target cells.' },
    { t: 'Polymers designed for a job', d: 'PTFE: strong C–F bonds make it inert and non-stick. PVC: rigid, made flexible by a plasticiser whose molecules get between the chains and weaken the forces between them. Kevlar: rigid chains hydrogen bonded into sheets, very strong (body armour). Poly(ethenol): its OH groups hydrogen bond to water, so it dissolves (soluble laundry bags). Poly(lactic acid): biodegradable packaging and stitches. Poly(ethyne): alternating double bonds with delocalised electrons, conducts electricity when doped.' },
    { t: 'The nanoscale', d: 'Nanoparticles are 1–100 nm across (1 nm = 10⁻⁹ m). Their surface area to volume ratio is enormous, so a large fraction of their atoms is at the surface. This makes them more reactive and better catalysts, and gives them optical and electrical properties different from the same material in bulk.' },
    { t: 'Carbon nanoparticles', d: 'Buckminsterfullerene, C₆₀: a hollow sphere of 60 carbon atoms arranged in 12 pentagons and 20 hexagons, each carbon bonded to three others with delocalised electrons; a simple molecular solid that dissolves in organic solvents and can cage other atoms. Nanotubes: sheets of graphene rolled into cylinders about 1 nm wide, with very high tensile strength, conducting electricity along the tube. Graphene: a single layer of graphite one atom thick; very strong, flexible, almost transparent and an excellent conductor.' },
    { t: 'Uses of nanoparticles', d: 'Catalysts with huge surface areas (platinum in catalytic converters and fuel cells). Titanium dioxide and zinc oxide in sunscreens: transparent on the skin but blocking UV. Silver nanoparticles as antibacterials in wound dressings and clothing. Nanotubes in strong, light composites and in electronics. Drug delivery. Risks: particles this small can enter the lungs and cells, and their long-term effects are not fully known.' },
    { t: 'Chemistry and environmental problems', d: 'Catalytic converters remove CO, NOₓ and unburnt hydrocarbons. Flue gas desulfurisation removes SO₂ with CaO or CaCO₃. HFCs replaced ozone-depleting CFCs, and lead was removed from petrol. Biodegradable polymers reduce plastic waste. Carbon capture and storage keeps CO₂ out of the atmosphere. Precipitation as hydroxides removes heavy metal ions from waste water.' },
    { t: 'Using natural resources efficiently', d: 'Green chemistry: choose reactions with high atom economy; use catalysts so processes run at lower temperatures and use less energy; use renewable feedstocks (bioethanol, biodiesel, poly(lactic acid)); replace hazardous solvents with water or supercritical CO₂; design products that break down safely. Recycling metals and polymers saves ores, crude oil and energy: recycled aluminium needs only about 5 % of the energy used to extract it.' }
  ]},

  { id: 'synthesis', title: 'Organic synthesis', area: 'organic', topic: 'synthesis', items: [
    { t: 'Routes from alkanes, alkenes and halogenoalkanes', d: 'Alkane + Cl₂ or Br₂, UV light: halogenoalkane. Alkene + H₂, Ni, 150 °C: alkane; + HBr: bromoalkane; + Br₂: dibromoalkane; + steam, H₃PO₄, 300 °C, 60 atm: alcohol. Halogenoalkane + aqueous NaOH, reflux: alcohol; + KCN in ethanol, reflux: nitrile; + excess ethanolic NH₃, sealed tube: amine; + KOH in ethanol, heat: alkene.' },
    { t: 'Routes from alcohols', d: 'Primary alcohol + acidified K₂Cr₂O₇, distil: aldehyde; heat under reflux: carboxylic acid. Secondary alcohol + acidified K₂Cr₂O₇: ketone. Alcohol + concentrated H₂SO₄ at 170 °C, or vapour over hot Al₂O₃: alkene. Alcohol + PCl₅, or KBr and concentrated H₂SO₄: halogenoalkane. Alcohol + carboxylic acid, concentrated H₂SO₄, reflux: ester.' },
    { t: 'Routes from carbonyls, acids and nitriles', d: 'Aldehyde or ketone + NaBH₄: primary or secondary alcohol; + HCN (KCN and dilute acid): 2-hydroxynitrile. Nitrile + dilute HCl, reflux: carboxylic acid; + LiAlH₄ or H₂/Ni: amine. Carboxylic acid + PCl₅ or SOCl₂: acyl chloride; + LiAlH₄: primary alcohol. Acyl chloride + water: acid; + alcohol: ester; + NH₃: amide; + amine: N-substituted amide.' },
    { t: 'Aromatic routes', d: 'Benzene + concentrated HNO₃ and H₂SO₄, 50 °C: nitrobenzene; then Sn and concentrated HCl under reflux, then NaOH: phenylamine. Benzene + Br₂ and FeBr₃: bromobenzene. Benzene + acyl chloride and AlCl₃: phenyl ketone; + halogenoalkane and AlCl₃: alkylbenzene. Alkylbenzene + hot alkaline KMnO₄, then acid: benzoic acid. Phenylamine + HNO₂ below 10 °C, then phenol in alkali: azo dye.' },
    { t: 'Changing the carbon chain', d: 'Add one carbon: halogenoalkane + KCN gives a nitrile; aldehyde or ketone + HCN gives a hydroxynitrile. Add a carbon group to a benzene ring: Friedel–Crafts. Shorten the chain: hot concentrated KMnO₄ splits a C=C; the iodoform reaction removes the CH₃ of a CH₃CO– group as CHI₃.' },
    { t: 'Planning a synthesis', d: 'Compare the starting material with the product: count the carbons, then list the functional groups to add, remove or change. Work backwards from the product. For each step give the reagent, the conditions (temperature, catalyst, solvent, reflux or distil) and the type of reaction. Fewer steps give a higher overall yield.' },
    { t: 'Overall yield', f: 'overall yield = yield₁ × yield₂ × … (as decimals) × 100 %', d: 'Two steps of 80 % and 70 % give 0.80 × 0.70 = 56 % overall. Losses come from incomplete or reversible reactions, side reactions, and transfer and purification.' },
    { t: 'Reflux and distillation', d: 'Heating under reflux: a vertical condenser returns the vapour to the flask, so a slow reaction can be heated for a long time without losing volatile reactants or products (oxidation to a carboxylic acid, ester hydrolysis). Distillation: the product is collected as it boils off, which removes an aldehyde before it is oxidised further. Add anti-bumping granules, and heat flammable organic liquids with a water bath or heating mantle, not a naked flame.' },
    { t: 'Purifying a product', d: 'Solid, by recrystallisation: dissolve in the minimum volume of hot solvent, filter hot to remove insoluble impurities, cool so the product crystallises while soluble impurities stay in solution, filter under reduced pressure, wash with a little cold solvent, dry. Liquid: wash in a separating funnel (sodium hydrogencarbonate solution removes acid), dry with an anhydrous salt such as MgSO₄ or CaCl₂, then distil and collect the fraction boiling at the product boiling point.' },
    { t: 'Checking purity', d: 'A pure solid melts sharply at its data-book melting point; impurities lower the melting point and widen the range. A pure liquid boils at a fixed temperature. Thin-layer chromatography shows a single spot. Infrared, NMR and mass spectra match the expected compound with no extra peaks.' },
    { t: 'Functional group tests at a glance', d: 'C=C: bromine water, orange to colourless. OH in alcohols and acids: sodium gives effervescence of H₂; PCl₅ gives steamy fumes of HCl. Primary or secondary alcohol, or aldehyde: acidified K₂Cr₂O₇, orange to green. C=O: 2,4-DNPH, orange precipitate. Aldehyde: Tollens\' reagent, silver mirror; Fehling\'s solution, brick-red precipitate. CH₃CO– or CH₃CH(OH)–: I₂ and NaOH, yellow CHI₃. COOH: Na₂CO₃ or NaHCO₃, effervescence of CO₂. Phenol: neutral FeCl₃, violet. Halogenoalkane: warm with aqueous NaOH, acidify with dilute HNO₃, add AgNO₃: white (Cl), cream (Br) or yellow (I) precipitate.' }
  ]},

  { id: 'analysis', title: 'Analytical techniques', area: 'analysis', topic: 'analysis', items: [
    { t: 'Mass spectrum of a compound', d: 'The molecular ion peak M⁺ at the highest m/z (ignoring M+1, M+2) gives Mr. The M+1 peak comes from ¹³C; its height relative to M is about 1.1 % × number of carbons. Chlorine gives M and M+2 peaks in the ratio 3 : 1 (³⁵Cl : ³⁷Cl); bromine gives M and M+2 in the ratio 1 : 1 (⁷⁹Br : ⁸¹Br). Two chlorines give M, M+2, M+4 as 9 : 6 : 1.' },
    { t: 'Common fragment ions', d: 'm/z 15 CH₃⁺; 29 C₂H₅⁺ or CHO⁺; 43 C₃H₇⁺ or CH₃CO⁺; 45 COOH⁺; 57 C₄H₉⁺; 77 C₆H₅⁺; 91 C₆H₅CH₂⁺. The base peak is the tallest, the most stable ion. Losing 15 means a methyl group was lost, losing 17 an OH, losing 18 water.' },
    { t: 'Infrared spectroscopy', d: 'Bonds vibrate and absorb infrared at characteristic wavenumbers (cm⁻¹). Typical: O–H in alcohols 3200–3600, broad. O–H in carboxylic acids 2500–3300, very broad, overlapping C–H. N–H 3300–3500. C–H 2850–3100. C≡N 2200–2260. C=O 1680–1750, strong and sharp (aldehyde, ketone, acid, ester, amide). C=C 1620–1680. C–O 1000–1300. Below 1500 is the fingerprint region, unique to the compound. Use the table in the data booklet in the exam.' },
    { t: 'Infrared and global warming', d: 'The Earth absorbs radiation from the Sun and re-emits it as infrared. Greenhouse gases such as CO₂, H₂O and CH₄ absorb this infrared because their bond vibrations change the dipole of the molecule; they re-emit it in all directions, some back toward the Earth, warming the lower atmosphere. N₂ and O₂ do not absorb infrared. The effect of a gas depends on how strongly it absorbs, its concentration and how long it stays in the atmosphere.' },
    { t: 'Proton (¹H) NMR', d: 'Number of peaks = number of different proton environments. Integration (peak area ratio) = ratio of protons in each environment. Splitting: a signal is split into n + 1 lines by n equivalent protons on the adjacent carbon (singlet 0, doublet 1, triplet 2, quartet 3). Reference TMS at δ = 0; solvent CDCl₃ or CCl₄ contains no ¹H. OH and NH signals are often broad singlets and disappear when the sample is shaken with D₂O.' },
    { t: 'Typical ¹H chemical shifts (δ / ppm)', d: 'R–CH₃ 0.9; R–CH₂–R 1.3; CH₃–C=O 2.0–2.3; CH₃–Ar 2.3; CH₂ next to halogen 3.0–4.0; CH–O in alcohols, ethers, esters 3.3–4.3; H–C=C 4.5–6.0; aromatic C–H 6.5–8.0; aldehyde CHO 9.5–10.0; carboxylic acid COOH 10–12. OH and NH vary with concentration.' },
    { t: 'Carbon-13 NMR', d: 'One peak per carbon environment (no splitting in the usual decoupled spectrum). Typical shifts: alkyl C 0–50; C–N 30–65; C–O in alcohols, ethers, esters 50–90; C=C and aromatic C 110–160; C=O in esters and acids 160–185; C=O in aldehydes and ketones 190–220.' },
    { t: 'Magnetic resonance imaging (MRI)', d: 'The medical use of NMR. The patient lies in a strong magnetic field and hydrogen nuclei, mostly in water and fat, absorb radio waves. Tissues differ in water content and environment, so they give different signals, and a computer builds an image of soft tissue. Non-invasive and uses no ionising radiation, unlike X-rays.' },
    { t: 'Chromatography', f: 'Rf = distance moved by the spot / distance moved by the solvent front', d: 'Components separate by partition between a stationary phase (paper, silica, a liquid on a solid) and a mobile phase (solvent or carrier gas). Paper and thin-layer chromatography: compare Rf values with known standards under the same conditions. Gas chromatography: retention time identifies each component and peak area is proportional to its amount; coupled to a mass spectrometer (GC–MS) for identification.' },
    { t: 'Electrophoresis', d: 'Charged particles move through a gel under an electric field; the direction depends on the sign of the charge and the distance on charge and size. Amino acids can be separated by choosing a pH: at its isoelectric point an amino acid does not move. DNA fragments separate by length (genetic fingerprinting).' },
    { t: 'Combustion analysis', d: 'Burn a known mass; n(C) from the mass of CO₂ (÷ 44.0), n(H) from the mass of H₂O (÷ 18.0, × 2), oxygen by difference. Convert to the empirical formula, then use Mr from the mass spectrum for the molecular formula.' },
    { t: 'Putting it together', d: 'Mr from the mass spectrum, functional groups from infrared, the carbon skeleton from the number, integration and splitting of NMR peaks, then confirm with chemical tests: bromine water for C=C, 2,4-DNPH for C=O, Tollens\' for aldehyde, sodium carbonate for COOH, iodoform for CH₃CO or CH₃CH(OH).' }
  ]}
];
